INSERT INTO `pasal-kontrak` (`id`, `nama_pasal`, `keterangan_pasal`, `isi_pasal`, `status_jaminan`, `jenis_kontrak`, `urutan`, `created_at`, `updated_at`) VALUES
	(1, 'PASAL 1', 'DEFINISI-DEFINISI', '<ol><li style="text-align: justify; "><b>Perjanjian</b> adalah Perjanjian ini yang dibuat dan ditandatangani antara Para Pihak, termasuk seluruh lampirannya dan setiap perubahan-perubahannya.</li><li style="text-align: justify;"><b>Barang</b> adalah barang berupa xyzxyz yang harus diadakan dan dipasok oleh PIHAK KEDUA sesuai Spesifikasi Teknis.</li><li style="text-align: justify;"><b>Spesifikasi</b> <b>Teknis</b> adalah Spesifikasi Teknis barang sebagaimana rinciannya yang dimaksud dalam Pasal 4 Perjanjian ini.</li><li style="text-align: justify;"><b>Bulan dan Hari</b> adalah bulan dan hari terkait yang tercantum dalam kalender Masehi.</li><li style="text-align: justify;"><b>Tanggal Berlakunya Perjanjian</b> adalah tanggal dimana semua ketentuan yang terdapat pada Pasal 24 terpenuhi.</li><li style="text-align: justify; "><b>Surat Penerimaan Barang ("SPB")</b> adalah pernyataan tertulis bertanggal dan diterbitkan oleh PIHAK KESATU yang menyatakan bahwa barang telah diserahkan dan diterima oleh PIHAK KESATU sesuai dengan Perjanjian.</li><li style="text-align: justify;"><b>Jaminan Mutu</b>&nbsp;adalah jaminan dari PIHAK KEDUA untuk senantiasa menjaga kualitas barang selama masa tertentu sebagaimana diatur dalam Pasal 14 Perjanjian ini.</li><li style="text-align: justify;"><b>Jaminan Pelaksanaan </b>adalah sebagaimana rinciannya yang dimaksud dalam Pasal 9 Perjanjian ini.</li><li style="text-align: justify;"><b>Pelindungan Data Pribadi </b>adalah keseluruhan upaya untuk melindungi Data Pribadi dalam rangkaian pemrosesan Data Pribadi guna menjamin hak konstitusional subjek Data Pribadi.</li><li style="text-align: justify;"><b>Undang-Undang Pelindungan Data Pribadi </b>adalah Undang-Undang No. 27 Tahun 2022 tentang Pelindungan Data Pribadi sebagaimana diubah dari waktu ke waktu.</li><li style="text-align: justify;"><b>Data Pribadi </b>adalah data tentang orang perseorangan yang terindentifikasi atau dapat diidentifikasi secara tersendiri atau dikombinasi dengan informasi lainnya baik secara langsung maupun tidak langsung melalui sistem elektronik atau non-elektronik.</li></ol>', 1, 2, 1, '2024-03-08 06:04:11', '2024-12-08 12:32:42'),
	(2, 'PASAL 2', 'KETENTUAN-KETENTUAN UMUM', '<ol><li style="text-align: justify; ">Apabila suatu ketentuan Perjanjian ini atau bagian dari padanya dianggap batal, tidak sah atau tidak dapat diberlakukan berdasarkan peraturan perundang-undangan yang berlaku terhadap mana ketentuan tersebut tunduk, maka ketentuan dimaksud dianggap batal, tidak sah atau tidak dapat diberlakukan dengan cara apapun, tidak berpengaruh pada atau mengurangi berlakunya bagian lain dari ketentuan tersebut atau ketentuan-ketentuan lainnya dari Perjanjian ini. </li><li style="text-align: justify;">Kelalaian salah satu Pihak dalam melaksanakan, dan keterlambatan satu Pihak melaksanakan hak berdasarkan Perjanjian ini, tidak berlaku sebagai pembebasan atau pengesampingan dari setiap pelaksanaan keseluruhan atau sebagian dari hak berdasarkan Perjanjian ini tidak mencegah pelaksanaan lain atau pelaksanaan selanjutnya dari hak tersebut.</li><li style="text-align: justify;">Perjanjian ini berlaku untuk kepentingan dan mengikat Para Pihak, para pengganti dan para penerima hak yang diijinkan masing-masing Pihak.</li><li style="text-align: justify;">Perjanjian ini menggantikan dan mengesampingkan semua dokumen, perjanjian, kesepakatan, atau pemahaman yang pernah dibuat sebelumnya, baik secara tertulis maupun lisan, yang berkaitan dengan objek dan ketentuan-ketentuan yang diatur dalam Perjanjian ini.</li></ol>', 1, 2, 2, '2024-03-08 06:04:11', '2024-12-08 12:35:34'),
	(3, 'PASAL 3', 'LINGKUP PERJANJIAN', 'Lingkup Perjanjian sebagaimana tercantum pada Lampiran II Perjanjian ini.', 1, 2, 3, '2024-03-08 06:04:11', '2024-10-17 08:26:08'),
	(4, 'PASAL 4', 'SPESIFIKASI TEKNIS', 'Spesifikasi teknis barang sebagaimana tercantum dalam Lampiran III Perjanjian ini.', 1, 2, 4, '2024-03-08 06:04:11', '2024-05-27 07:43:23'),
	(5, 'PASAL 5', 'JADWAL PENYERAHAN BARANG', 'Jadwal penyerahan barang sebagaimana dimaksud dalam Lampiran IV Perjanjian ini.', 1, 2, 5, '2024-03-08 06:04:11', '2024-05-27 07:43:34'),
	(6, 'PASAL 6', 'PERUBAHAN JADWAL PENYERAHAN BARANG', '<ol><li style="text-align: justify; ">Jadwal penyerahan Barang dimaksud Pasal 5 Perjanjian ini dapat berubah sewaktu-waktu sesuai permintaan PIHAK KESATU, yang mana permintaan tersebut dibuat secara tertulis oleh dan dari PIHAK KESATU kepada PIHAK KEDUA, yang selanjutnya diperlukan adanya persetujuan dari PIHAK KEDUA dengan tetap memperhatikan situasi dan kondisi proses produksi.</li><li style="text-align: justify;">Perubahan dimaksud ayat (1) Pasal ini akan dituangkan dalam suatu Addendum Lampiran IV, yang merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.\r\n</li></ol>', 1, 2, 6, '2024-03-08 06:04:11', '2024-12-08 12:37:21'),
	(7, 'PASAL 8', 'HARGA BARANG', 'Harga barang sebagaimana tercantum dalam Lampiran  V  Perjanjian ini.', 1, 2, 8, '2024-03-08 06:26:53', '2024-10-17 04:11:01'),
	(8, 'PASAL 9', 'JAMINAN PELAKSANAAN', '<ol><li>PIHAK KEDUA harus menyerahkan kepada PIHAK KESATU Jaminan Bank untuk Jaminan Pelaksanaan (<i>Performance Bond</i>) dari Bank BUMN/BUMD sebesar 5% (lima persen) dari total harga Barang secara keseluruhan seperti dimaksud Pasal 8 Perjanjian ini.</li><li>Jaminan Pelaksanaan yang dimaksud ayat (1) Pasal ini harus mempunyai masa berlaku sampai dengan pelaksanaan Perjanjian selesai secara 100% (seratus persen) yang dinyatakan dengan SPB.</li><li>Apabila Jaminan Pelaksanaan dimaksud ayat (1) Pasal ini akan habis masa berlakunya sementara pelaksanaan Perjanjian belum selesai, maka PIHAK KEDUA berkewajiban untuk memperpanjang masa berlaku Jaminan Pelaksanaan tersebut selambat-lambatnya dalam waktu 7 (tujuh) hari kalender sebelum habis masa berlakunya Jaminan Pelaksanaan tersebut.</li><li>Apabila PIHAK KEDUA baik lalai ataupun sengaja tidak menyerahkan Jaminan Pelaksanaan yang telah diperpanjang masa berlakunya dalam waktu paling lambat 5 (lima) hari kalender sebelum Jaminan Pelaksanaan yang dimaksud dalam ayat (1) Pasal ini jatuh tempo, maka PIHAK KESATU berhak secara sepihak tanpa perlu adanya pemberitahuan terlebih dahulu kepada PIHAK KEDUA untuk mencairkan Jaminan Pelaksanaan tersebut pada saat berakhirnya Jaminan Pelaksanaan dan PIHAK KESATU berhak pula untuk menahan pembayarannya serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li>Apabila PIHAK KEDUA lalai memenuhi kewajibannya sesuai dengan syarat-syarat dan ketentuan-ketentuan dalam Perjanjian ini dan atau Perjanjian ini dibatalkan karena kesalahan PIHAK KEDUA, maka Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li>Jaminan Pelaksanaan dimaksud ayat (1) dan (2) Pasal ini akan dikembalikan oleh PIHAK KESATU kepada PIHAK KEDUA apabila pelaksanaan Perjanjian ini telah selesai secara 100% (seratus persen) yang dinyatakan dengan SPB.<br></li></ol>', 1, 2, 9, '2024-03-08 06:26:53', '2024-12-08 12:40:05'),
	(9, 'PASAL 10', 'PENERIMAAN DAN PEMERIKSAAN BARANG', '<ol><li>Barang yang telah diterima dari PIHAK KEDUA di gudang milik PIHAK KESATU di Karawang diperlukan sebagai penerimaan sementara sampai dengan prosedur pemeriksaan Barang di PIHAK KESATU selesai dilaksanakan, tanpa mengurangi hak PIHAK KESATU untuk mempergunakan Barang tersebut dan masih berada di bawah tanggung jawab PIHAK KEDUA apabila ditemukan kerusakan dan atau ketidaksesuaian spesifikasinya.</li><li>Selanjutnya terhadap Barang yang telah diterima di gudang milik PIHAK KESATU di Karawang tersebut pada ayat (1) Pasal ini dilakukan pemeriksaan oleh PIHAK KESATU sesuai dengan prosedur pemeriksaan yang berlaku di PIHAK KESATU.</li><li>Apabila Barang oleh PIHAK KESATU dinyatakan tidak baik atau tidak sesuai dengan Spesifikasi Teknis, maka PIHAK KEDUA harus segera mengambil Barang tersebut dalam waktu selambat-lambatnya 7 (tujuh) hari kalender setelah tanggal pemberitahuan oleh PIHAK KESATU dan harus menggantinya dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender sejak tanggal pemberitahuan oleh PIHAK KESATU atau dikembalikan pembayarannya oleh PIHAK KEDUA apabila terjadi ketidaksesuaian dengan Jaminan Mutu.</li><li>Barang pengganti seperti yang dimaksud ayat (3) Pasal ini harus diserahkan dalam keadaan lengkap, baik dan sesuai Spesifikasi Teknis yang mana terhadap Barang pengganti tersebut diberlakukan juga pemeriksaan seperti yang dimaksud ayat (2) Pasal ini.</li><li>Barang yang oleh PIHAK KESATU dinyatakan baik dan sesuai dengan Spesifikasi Teknis atau persyaratan yang ditetapkan PIHAK KESATU akan dibuatkan SPB dan PIHAK KEDUA tetap harus mempertahankan Jaminan Mutu sebagaimana disepakati.</li><li>Apabila PIHAK KEDUA melanggar ketentuan ayat (3) dan (4) Pasal ini, maka PIHAK KESATU secara sepihak berhak membatalkan Surat Order Pembelian (<b>"SOP"</b>) dan atau Perjanjian ini tanpa adanya tuntutan dari PIHAK KEDUA maupun pihak ketiga lainnya atas pelaksanaan Perjanjian ini. serta PIHAK KESATU berhak mengalihkan pelaksanaan Perjanjian ini pada pihak lain serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li></ol>', 1, 2, 10, '2024-03-08 06:26:53', '2024-12-08 12:53:34'),
	(10, 'PASAL 11', 'PEMBAYARAN', '<p style="text-align: justify; ">Pembayaran dari PIHAK KESATU kepada PIHAK KEDUA dilakukan sebagaimana tercantum dalam Lampiran VI Perjanjian ini.<br></p>', 1, 2, 11, '2024-03-08 06:29:46', '2024-05-27 07:45:45'),
	(11, 'PASAL 12', 'PENGALIHAN KEPADA PIHAK KETIGA', '<ol><li style="text-align: justify; ">PIHAK KEDUA tidak diperbolehkan untuk mengalihkan pelaksanaan ruang lingkup Perjanjian ini, baik sebagian maupun keseluruhannya kepada pihak ketiga maupun kecuali diperbolehkan berdasarkan ketentuan Pasal 12 ini.</li><li style="text-align: justify;">PIHAK KEDUA hanya dapat melakukan pengalihan baik sebagian maupun keseluruhan kepada pihak ketiga atas dasar terjadinya hal tertentu dan/atau keadaan memaksa sebagaimana dimaksud Pasal 17 Perjanjian ini dan setelah mendapatkan persetujuan tertulis dari PIHAK KESATU.</li><li style="text-align: justify; ">Tunduk kepada ketentuan ayat (2) di atas, maka :<ul><li style="text-align: justify; ">PIHAK KEDUA bertanggungjawab penuh terhadap Jaminan Mutu.</li><li style="text-align: justify; ">PIHAK KEDUA bertanggungjawab penuh dan akan memberikan ganti rugi kepada PIHAK KESATU apabila pengalihan kepada pihak ketiga tersebut mengalami kegagalan, kerusakan yang dapat merugikan PIHAK KESATU.</li><li style="text-align: justify; ">PIHAK KEDUA harus mengawasi pelaksanaan oleh pihak ketiga atas ruang lingkup yang dialihkan tersebut dan melaporkan kepada PIHAK KESATU.</li><li style="text-align: justify; ">PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan/gugatan dan klaim dari pihak ketiga manapun termasuk namun tidak terbatas dari pihak ketiga sehubungan dengan pelaksanaan pengalihan tersebut.</li></ul></li><li style="text-align: justify;">Apabila ketentuan ayat (1), ayat (2) dan ayat (3) Pasal ini dilanggar oleh PIHAK KEDUA, maka PIHAK KESATU secara sepihak berhak membatalkan Perjanjian ini tanpa adanya tuntutan apapun dari PIHAK KEDUA, dan PIHAK KESATU berhak memberikan pelaksanaan pekerjaan tersebut kepada pihak lain serta apabila ada Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li></ol>', 1, 2, 12, '2024-03-08 06:29:46', '2024-12-08 13:01:03'),
	(12, 'PASAL 13', 'PESANAN TAMBAH KURANG', '<ol><li style="text-align: justify; ">PIHAK KESATU setiap saat dapat mengubah lingkup pelaksanaan Perjanjian seperti penambahan atau pengurangan pesanan barang.</li><li style="text-align: justify; ">Jika perubahan dalam ayat (1) Pasal ini mengakibatkan penambahan atau pengurangan harga dan atau perubahan jadwal penyerahan Barang pada SOP, maka akan dilakukan penyesuaian harga  dan atau jadwal penyerahan barang pada SOP, yang akan dituangkan dalam suatu surat perubahan SOP dan merupakan bagian yang tidak terpisahkan dari Perjanjian ini.</li><li style="text-align: justify;">Harga satuan pesanan tambah kurang dalam SOP tidak boleh melebihi dari harga satuan  yang telah disepakati sebelumnya sebagaimana tercantum dalam dimaksud Pasal 8 Perjanjian ini.</li><li style="text-align: justify;">Pesanan tambah kurang baru dapat dilaksanakan oleh PIHAK KEDUA setelah  PIHAK KEDUA menerima Surat Pemberitahuan dari PIHAK KESATU mengenai perubahan pesanan tersebut.</li></ol>', 1, 2, 13, '2024-03-08 06:38:51', '2024-12-08 13:04:46'),
	(13, 'PASAL 14', 'JAMINAN MUTU BARANG', '<ol><li>PIHAK KEDUA memberikan jaminan Mutu atas Barang dimana Barang yang dijual dan diserahkan kepada PIHAK KESATU adalah 100% (seratus persen) baru dan sesuai dengan ketentuan-ketentuan dan syarat-syarat yang ditetapkan dalam Perjanjian ini beserta Lampirannya, karena itu PIHAK KEDUA bertanggung jawab atas segala ketidaksesuaian mutu atas Barang termasuk tetapi tidak terbatas cacat tersembunyi ataupun kekurang sempurnaan dalam proses pembuatannya.</li><li>Masa Jaminan Mutu (garansi) atas barang menurut Perjanjian ini adalah selama 12 (dua belas) bulan setelah keluarnya Surat Penerimaan Barang (SPB) dari Gudang PIHAK KESATU.</li><li>Jaminan ini tidak berlaku bilamana dapat dibuktikan oleh PIHAK KEDUA bahwa ketidaksesuaian mutu atas Barang dimaksud Pasal ini disebabkan oleh karena kesalahan dalam pemakaian oleh PIHAK KESATU, namun yang terbukti bukan karena kesalahan dalam proses pembuatan ataupun juga karena kualitas bahan yang digunakan, hal mana harus dibuktikan oleh PIHAK KEDUA dan dapat meyakinkan PIHAK KESATU.</li><li>Dalam hal terjadi ketidaksesuaian mutu atas Barang dimaksud Pasal ini maka PIHAK KESATU akan memberitahukan secara tertulis dalam jangka waktu selambat-lambatnya 7 (tujuh) hari kalender setelah ketidaksesuaian mutu atas Barang tersebut ditemukan, PIHAK KEDUA berkewajiban untuk memperbaiki dan atau menggantikannya dengan Barang yang baru dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender terhitung sejak tanggal pemberitahuan dari PIHAK KESATU, kecuali apabila PIHAK KEDUA dapat membuktikan bahwa ketidaksesuaian mutu atas Barang tersebut adalah terjadi karena sebab dimaksud ayat (3) Pasal ini.</li><li>Segala ongkos, biaya-biaya serta pengeluaran lain yang timbul karena penggantian dan atau perbaikan barang tersebut menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 1, 2, 14, '2024-03-08 06:38:51', '2024-12-08 13:06:34'),
	(14, 'PASAL 15', 'JAMINAN HUKUM ATAS BARANG', '<ol><li>PIHAK KEDUA menjamin bahwa Barang yang diserahkan kepada PIHAK KESATU tidak diperoleh dari hal-hal yang bertentangan dengan hukum.</li><li>PIHAK KEDUA menjamin bahwa Barang yang diserahkan berdasarkan Perjanjian ini tidak melanggar Hak Atas Kekayaan Intelektual (HAKI) atau hak lain yang dimiliki pihak ketiga.</li><li>Jika terjadi klaim atau tuntutan lainnya sehubungan dengan hal tersebut pada ayat (1) dan (2) Pasal ini, PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan apapun dan dimanapun yang mungkin timbul serta PIHAK KEDUA dengan ini menyatakan akan mengambil segala tindakan hukum yang diperlukan termasuk mewakili di&nbsp; depan pengadilan.</li><li>Apabila klaim atau tuntutan pihak ketiga sebagaimana dimaksud ayat (1) dan (2) Pasal ini dikabulkan oleh Pengadilan atau oleh Badan apapun, maka PIHAK KEDUA menjamin bahwa barang tersebut tetap dapat dipergunakan dan menjadi milik PIHAK KESATU.<br></li></ol>', 1, 2, 15, '2024-03-08 06:38:51', '2024-12-08 13:07:49'),
	(15, 'PASAL 16', 'SANKSI', '<ol><li style="text-align: justify; ">Apabila jadwal penyerahan barang sebagaimana dimaksud Pasal 5 Perjanjian ini terlampaui maka PIHAK KEDUA akan dikenakan sanksi berupa denda keterlambatan sebesar 1‰ (satu permil) setiap hari kalender keterlambatan dari harga Barang seperti yang dimaksud Pasal 7 Perjanjian ini dengan batas maksimum denda keterlambatan sebesar 5% (lima persen) dari total harga Barang tersebut tidak termasuk Pajak Pertambahan Nilai (PPN), yang dapat dipotong secara sekaligus dari tagihan PIHAK KEDUA yang belum dibayar PIHAK KESATU.</li><li style="text-align: justify;">Apabila denda keterlambatan sudah mencapai batas maksimum sebagaimana dimaksud dalam ayat (1) Pasal ini atau waktu keterlambatan sudah mencapai 50 (lima puluh) hari kalender, maka PIHAK KEDUA dipandang tidak mampu untuk menyelesaikan Perjanjian ini, sehingga PIHAK KESATU berhak secara sepihak untuk memutuskan/membatalkan Perjanjian ini serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify;">Segala kerugian nyata yang disebabkan oleh keterlambatan seperti yang dimaksud Pasal ini akan dibebankan kepada PIHAK KEDUA, kerugian tersebut termasuk tetapi tidak terbatas denda pihak ketiga terhadap PIHAK KESATU dan biaya-biaya lain yang timbul.</li><li style="text-align: justify;">Segala kerugian nyata yang diderita PIHAK KESATU akibat ketidaksesuaian mutu atas Barang seperti yang dimaksud Pasal 14 Perjanjian ini, dan/atau kesalahan PIHAK KEDUA, termasuk tetapi tidak terbatas pada denda pihak ketiga terhadap PIHAK KESATU akan dibebankan kepada PIHAK KEDUA.</li><li style="text-align: justify;">Apabila ternyata PIHAK KEDUA tidak dapat memenuhi ketentuan-ketentuan Perjanjian ini atau menurut pertimbangan PIHAK KESATU bahwa PIHAK KEDUA dipandang tidak mampu memenuhi ketentuan-ketentuan dalam Perjanjian ini, maka PIHAK KESATU secara sepihak berhak memutuskan/membatalkan Perjanjian ini. Hal yang sama dapat pula dilakukan apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify;"><span style="font-size: 1rem;">Ketentuan sanksi seperti yang dimaksud Pasal ini tidak berlaku apabila :</span><ul><li style="text-align: justify;"><span style="font-size: 1rem;">Suatu keterlambatan seperti yang dimaksud Pasal ini disebabkan karena perintah secara tertulis dari PIHAK KESATU kepada PIHAK KEDUA untuk menunda atau menghentikan sementara waktu pelaksanaan penyerahan barang seperti yang dimaksud Pasal 5 Perjanjian ini.</span></li><li style="text-align: justify;"><span style="font-size: 1rem;">PIHAK KEDUA dapat membuktikan dan dapat meyakinkan PIHAK KESATU bahwa segala ketidak sesuaian mutu atas barang seperti yang dimaksud Pasal 14 Perjanjian ini adalah di luar kesalahan PIHAK KEDUA.<br></span></li></ul></li></ol>', 1, 2, 16, '2024-03-08 06:38:51', '2024-12-08 13:10:40'),
	(16, 'PASAL 17', 'KEADAAN MEMAKSA', '<ol><li><span style="font-size: 1rem;">Yang dimaksud dengan Keadaan Memaksa \r\nadalah keadaan-keadaan yang disebabkan oleh kejadian-kejadian di luar \r\nkesalahan atau kekuasaan dari Para Pihak yang merintangi atau \r\nmenghalangi pihak tersebut dalam menjalankan kewajibannya memenuhi \r\nPerjanjian ini, seperti :</span><ul><li><span style="font-size: 1rem;">Gempa bumi besar, angin topan, banjir besar, kebakaran besar, tanah longsor dan wabah penyakit.</span></li><li><span style="font-size: 1rem;">Pemogokan umum, huru-hara, sabotase, pemberontakan dan Kebijaksanaan Pemerintah di Bidang Moneter.</span></li><li><span style="font-size: 1rem;">Kejadian-kejadian lain di luar kekuasaan atau kemampuan dari para pihak.<br></span></li></ul></li><li>Dalam hal Keadaan Memaksa yang dimaksud ayat (1) Pasal ini terjadi, maka pihak yang terkena Keadaan Memaksa wajib memberitahukan secara tertulis kepada pihak lainnya dalam jangka waktu 7 (tujuh) hari kalender dari sejak terjadinya Keadaan Memaksa dan diterangkan secara resmi oleh Pejabat yang berwenang mengeluarkannya.</li><li>Kelalaian atau keterlambatan pihak yang terkena Keadaan Memaksa dalam menyampaikan pemberitahuannya yang dimaksud ayat (2) Pasal ini, mengakibatkan tidak diakuinya peristiwa dimaksud ayat (1) Pasal ini sebagai peristiwa Keadaan Memaksa oleh pihak lainnya.</li><li>Kejadian-kejadian dimaksud dalam ayat (1) Pasal ini dapat diperhitungkan sebagai perpanjangan waktu kewajiban yang harus dilaksanakan oleh pihak yang terkena Keadaan Memaksa apabila ketentuan dalam ayat (2) Pasal ini dipenuhi, dimana perpanjangan waktu tersebut akan dimusyawarahkan lebih lanjut oleh kedua belah pihak yang syarat-syarat dan ketentuan-ketentuan disetujui bersama yang dituangkan dalam suatu Perjanjian baru.</li><li>Semua kerugian dan biaya-biaya yang diderita oleh salah satu pihak sebagai akibat Keadaan Memaksa bukan merupakan tanggung jawab pihak lainnya.</li></ol>', 1, 2, 17, '2024-03-08 06:38:51', '2024-12-08 13:11:37'),
	(17, 'PASAL 18', 'PEMBATALAN PERJANJIAN', '<ol><li>PIHAK KESATU berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi :<ul><li>Apabila PIHAK KEDUA terbukti tidak dapat menyelenggarakan Perjanjian yang dimaksud pada Pasal 4, 5 Perjanjian ini atau dipandang oleh PIHAK KESATU bahwa PIHAK KEDUA tidak mampu melaksanakan Perjanjian dimaksud Pasal 3 Perjanjian ini.</li><li>Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 10 ayat (6) Perjanjian ini.</li><li>Apabila PIHAK KEDUA terbukti melanggar ketentuan Pasal 12 ayat (2) dan (3) Perjanjian ini.</li><li>Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 17 ayat (2) dan (4) Perjanjian ini.</li><li>Apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang.<br></li></ul></li><li>PIHAK KEDUA&nbsp;berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi :&nbsp;<ul><li>Apabila PIHAK KESATU dinyatakan jatuh pailit oleh yang berwenang.</li><li>Apabila PIHAK KESATU gagal dalam memenuhi ketentuan Pasal 17 ayat (2) dan (4) Perjanjian ini.</li></ul></li><li>Untuk hal ihwal pembatalan Perjanjian dimaksud ayat (1) Pasal ini, Para Pihak dengan ini menyatakan sepakat dan berjanji untuk mengesampingkan berlakunya ketentuan Pasal 1266 dan Pasal 1267 Undang-undang Hukum Perdata terhadap Perjanjian ini, sehingga pembatalan Perjanjian ini dapat dilakukan secara sah cukup dengan surat pemberitahuan dari PIHAK KESATU kepada PIHAK KEDUA tanpa menunggu adanya keputusan dari Hakim serta dengan ini PIHAK KEDUA menyatakan melepaskan hak-hak yang timbul dari padanya apabila ada.</li><li>Dalam hal Perjanjian ini dibatalkan, maka Para Pihak secara bersama-sama mengadakan inventarisasi terhadap hak dan kewajiban yang ada dan apabila terdapat kekurangan atau kelebihan pembayaran oleh PIHAK KESATU, maka akan diadakan penambahan pembayaran oleh PIHAK KESATU atau pengembalian pembayaran oleh PIHAK KEDUA.</li><li>Dalam hal Perjanjian ini dibatalkan, maka PIHAK KEDUA dengan ini berjanji dan menyatakan membebaskan PIHAK KESATU dari segala tuntutan hukum, termasuk tuntutan dari pihak ketiga serta ganti rugi berupa apapun dan dari manapun karena batalnya Perjanjian ini, oleh karena itu sepenuhnya menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 1, 2, 18, '2024-03-08 06:38:51', '2024-12-08 13:16:09'),
	(18, 'PASAL 19', 'PENYELESAIAN PERSELISIHAN', '<ol><li style="text-align: justify; ">Apabila dikemudian hari terjadi perselisihan dalam penafsiran dan atau pelaksanaan ketentuan-ketentuan dari Perjanjian ini dan atau hal-hal lainnya maka Para Pihak telah sepakat dan berjanji untuk terlebih dahulu menyelesaikan secara musyawarah untuk mencapai mufakat.</li><li style="text-align: justify; ">Bilamana cara musyawarah tersebut ayat (1) Pasal ini tidak dicapai kata sepakat dalam penyelesaian perselisihan, maka Para Pihak sepakat dan berjanji untuk menyelesaikan seluruh sengketa yang timbul dari Perjanjian ini kepada Badan Arbitrase Nasional Indonesia (BANI), untuk diselesaikan pada tingkat pertama dan terakhir menurut peraturan dan prosedur BANI. Arbitrase akan diselesaikan oleh 3 (tiga) orang Arbiter yang ditunjuk sebagai berikut :<ul><li style="text-align: justify; ">Masing-masing dari Para Pihak harus menunjuk 1 (satu) Arbiter dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal suatu permintaan untuk Arbitrase telah dikeluarkan oleh pihak yang meminta atau para pihak lain telah bersama-sama setuju membawa perselisihan kepada Arbitrase dan kedua Arbiter yang ditunjuk secara bersama-sama akan menunjuk Arbiter ketiga yang akan menjadi Ketua Arbitrase.</li><li style="text-align: justify; ">Apabila salah satu dari para pihak gagal menunjuk Arbiternya dalam jangka waktu sebagaimana dinyatakan di atas, Arbiter yang telah ditunjuk akan duduk sendiri sebagai Arbitrase dan memberikan Keputusan.</li><li style="text-align: justify; ">Namun apabila kedua Arbiter gagal menunjuk Arbiter ketiga dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal penunjukan kedua Arbiter, maka Ketua BANI atau Pejabat BANI yang berwenang akan menunjuk Arbiter ketiga sebagai Ketua Arbiter atas permintaan salah satu pihak.<br></li></ul></li><li style="text-align: justify;">Para pihak harus menanggung biaya Arbitrase secara sama rata dan proses Arbitrase harus dilangsungkan di Jakarta.</li><li style="text-align: justify;">Kecuali dalam ayat (2) sub b. Pasal ini, Keputusan Badan Arbitrase diambil berdasarkan suara terbanyak dan bersifat mengikat kedua belah pihak terhadap para pihak.</li><li style="text-align: justify;">Para pihak telah sepakat dan berjanji untuk secara tegas menentukan tidak ada banding atau penghentian pelaksanaan yang diajukan ke Pengadilan atas Keputusan Badan Arbitrase dan para pihak tidak akan menolak atau menentang pelaksanaan keputusan yang dilakukan oleh pihak untuk keuntungan siapa keputusan Badan Arbitrase telah diberikan.</li><li style="text-align: justify; ">Tiada satu pihak berhak untuk memulai atau melakukan tindakan di Pengadilan terhadap segala masalah dalam sengketa sampai dengan masalah tersebut telah diputuskan sebagaimana diatur di sini, kecuali untuk pelaksanaan keputusan Badan Arbitrase.</li><li style="text-align: justify;">Selama proses Arbitrase dan sampai Arbitrase memberikan keputusannya, para pihak setuju untuk terus melaksanakan semua kewajibannya masing-masing berdasarkan Perjanjian ini tanpa berprasangka atau menduga atas putusan akhir yang diambil oleh para Arbiter tersebut.</li><li style="text-align: justify;">Para pihak setuju memberlakukan penunjukan tidak akan berakhir pada tanggal setelah 6 (enam) bulan kalender sejak tanggal penunjukannya dan mandat kepada Arbitrase (wasit-wasit) sebagaimana yang ditetapkan sesuai dengan keputusan ini, akan tetap berlangsung sampai keputusan telah diambil oleh Badan Arbitrase.</li><li style="text-align: justify;">Keputusan Badan Arbitrase dapat dilaksanakan di setiap Pengadilan dimanapun yang mempunyai yurisdiksi yang berwenang terhadap masing-masing para pihak atau harta kekayaannya.</li></ol>', 1, 2, 19, '2024-03-08 06:44:14', '2024-12-08 13:17:12'),
	(19, 'PASAL 20', 'KETENTUAN MENJAGA RAHASIA', '<ol><li style="text-align: justify; ">Para Pihak sepakat melakukan usaha-usaha mereka yang terbaik untuk menjaga kerahasiaan Informasi sehubungan dengan Perjanjian ini dan  Para Pihak harus memastikan direktur-direktur, pegawai-pegawai, agen-agen atau pembantu-pembantu mereka tidak akan mengungkapkan informasi, data, dokumentasi dan pengetahuan kepada Pihak Ketiga tanpa persetujuan tertulis dari pihak yang lain, tidak juga akan menerbitkan informasi, data, dokumentasi dan pengetahuan dalam bentuk cetakan, kaset, disket, disk atau bentuk-bentuk lain, kecuali sepanjang tindakan dilakukan sebagai laporan kepada instansi pemerintah terkait sebagaimana diperlukan oleh undang-undang.</li><li style="text-align: justify; ">Kecuali informasi yang teridentifikasi dibuka oleh pihak pemberi informasi kepada pihak lain, bila dibuka secara tertulis berlabel “<i>proprietary</i>” atau “<i>confidential</i>” atau setiap label yang mempunyai arti yang semacam, atau bila dibuka secara lisan, yang harus dituangkan dalam tulisan dalam jangka waktu 30 (tiga puluh) hari dan berlabel ”<i>proprietary</i>” atau “<i>confidential</i>” atau setiap label yang memiliki arti yang semacam (informasi rahasia) tetap menjadi milik pihak pemberi informasi.</li><li style="text-align: justify; ">Kecuali untuk hak-hak khusus yang diberikan oleh Perjanjian ini, pihak penerima informasi tidak boleh menggunakan setiap informasi rahasia untuk kepentingannya sendiri. Pihak penerima informasi harus menggunakan tingkatan pemeliharaan tertinggi yang wajar secara komersial untuk memproteksi informasi rahasia dari pihak pemberi informasi. Pihak penerima informasi tidak boleh membuka informasi rahasia kepada Pihak Ketiga manapun tanpa persetujuan tertulis yang tegas dari pihak pemberi informasi.</li><li style="text-align: justify; ">Informasi rahasia tidak mencakup informasi :<ul><li style="text-align: justify; ">Yang tersedia kepada pihak publik selain dari pada karena wanprestasi karena Perjanjian ini.</li><li style="text-align: justify; ">Yang secara sah diterima dari Pihak Ketigas yang tidak melanggar kewajiban kerahasiaan.</li><li style="text-align: justify; ">Yang secara independen dikembangkan oleh pihak penerima informasi tanpa akses pada informasi rahasia.</li><li style="text-align: justify; ">Yang diberitahukan kepada pihak penerima informasi pada waktu dilangsungkan keterbukaan; atau</li><li style="text-align: justify; ">Yang dibuat sesuai dengan ketentuan hukum atau perintah pengadilan, dengan ketentuan pihak pemberi informasi diberikan pengetahuan yang wajar mengenai ketentuan hukum atau perintah pengadilan tersebut dan kesempatan untuk mencabut untuk mengecualikan atau membatasi perbuatan tersebut.</li></ul></li><li style="text-align: justify; ">Pihak penerima informasi setuju untuk menghentikan penggunaan setiap dan semua bahan yang memuat informasi rahasia kepada pihak pemberi informasi ketika diminta.<br></li></ol>', 1, 2, 20, '2024-03-27 04:30:38', '2024-12-08 13:18:07'),
	(20, 'PASAL 21', 'HUKUM YANG BERLAKU', '<ol><li style="text-align: justify;">Perjanjian ini tunduk dan berada di bawah ketentuan hukum Republik Indonesia.</li><li style="text-align: justify;">Pihak KEDUA harus mematuhi semua peraturan perundang-undangan dan kebijakan pemerintah yang berlaku di Indonesia.<br></li></ol>', 1, 2, 21, '2024-03-08 06:44:14', '2024-12-08 13:18:25'),
	(21, 'PASAL 22', 'PELINDUNGAN DATA PRIBADI', '<div style="text-align: justify;"><span style="font-size: 1rem;">Para Pihak dengan ini mengakui dan memahami setiap kewajiban Para Pihak dalam upaya Pelindungan Data Pribadi sesuai dengan ketentuan yang berlaku, antara lain :</span></div><ol><li style="text-align: justify;">Memproses Data Pribadi sesuai Undang-Undang Perlindungan Data Pribadi dan ketentuan dalam Peraturan Perundang-undangan lainnya.<br></li><li style="text-align: justify;">Hanya memproses Data Pribadi apabila dan hanya sejauh diperlukan agar dapat melaksanakan kewajiban berdasarkan Perjanjian.</li><li style="text-align: justify;">Tidak mengungkapkan Data Pribadi kepada pihak ketiga manapun selain :<ul><li style="text-align: justify;">Karyawan, direksi, afiliasi berdasarkan kebutuhan (<i>need-to know</i>) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini;</li><li style="text-align: justify;">Subkontraktor atau penasehat professional yang diizinkan secara tertulis oleh Para Pihak untuk memproses Data Pribadi berdasarkan kebutuhan (<i>need-to know basis</i>) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini; atau</li><li style="text-align: justify;">Sejauh diperlukan oleh peraturan perundang-undangan yang berlaku, namun tetap memperhatikan dan mematuhi Undang-Undang Perlindungan Data. Dalam hal tersebut, Pihak yang berkepentingan harus memberikan pemberitahuan tertulis kepada Pihak lainnya untuk mengungkapkan Data Pribadi (sejauh diizinkan oleh peraturan perundang-undangan yang berlaku) segera mungkin setelah mengetahui persyaratan tersebut.<br></li></ul></li><li style="text-align: justify;">Memastikan bahwa personilnya yang memproses Data Pribadi melaksanakan hal tersebut dan tetap patuh terhadap kewajiban kerahasiaan; dan</li><li style="text-align: justify;">Melaksanakan dan mempertahankan tindakan atau langkah administratif, teknis dan organisasi yang cukup:<ul><li style="text-align: justify;">Untuk menjaga keamanan Data Pribadi; dan</li><li style="text-align: justify;">Untuk mencegah penghapusan tidak sah atau tidak disengaja, perubahan tidak sah, menyalin, mengakses atau menggunakan, pemalsuan, pencurian, kehilangan atau kesalahan teknis sehubungan dengan Data Pribadi.<br></li></ul></li><li style="text-align: justify;">Para Pihak bertanggung jawab atas kerugian terhadap pelanggaran ketentuan terkait Data Pribadi yang diakibatkan oleh kelalaian personilnya serta akan bertanggung jawab penuh, termasuk namun tidak terbatas pada segala klaim, tuntutan, gugatan, sengketa, dan/atau ganti kerugian yang mungkin timbul dari pelanggaran ketentuan terkait Data Pribadi.<br></li></ol>', 1, 2, 22, '2024-03-08 06:44:14', '2024-12-08 13:19:55'),
	(22, 'PASAL 23', 'LARANGAN PEMBERIAN HADIAH DAN KOMISI', '<ol><li style="text-align: justify; ">PIHAK KEDUA dilarang untuk menerima penawaran atau menyetujui pemberian hadiah, komisi, potongan atau bentuk-bentuk lain yang sejenis dari Direksi, staff/karyawan dari PIHAK KESATU untuk tujuan ditandatanganinya dan/atau pelaksanaan Perjanjian ini.</li><li style="text-align: justify; ">Pelanggaran terhadap ayat 1 Pasal ini oleh PIHAK KEDUA atau karyawannya atau pihak lain yang bekerja untuk PIHAK KEDUA dapat mengakibatkan pembatalan Perjanjian ini oleh PIHAK KESATU, dan biaya yang timbul dari pembatalan tersebut akan menjadi tanggung jawab PIHAK KEDUA, dan PIHAK KEDUA akan dieliminasi sebagai mitra bisnis PIHAK KESATU.</li><li style="text-align: justify;">Pelanggaran dari setiap ketentuan dalam Pasal ini akan mengakibatkan gugatan pidana terhadap PIHAK KEDUA. Dalam hal terjadi penindaklanjutan atas adanya tindakan penerimaan komisi atau hadiah yang berpotensi merugikan PIHAK KESATU, semua biaya, ongkos dan kerugian yang timbul akan menjadi tanggung jawab PIHAK KEDUA. </li></ol>', 1, 2, 23, '2024-03-27 04:33:42', '2024-12-08 13:21:16'),
	(23, 'PASAL 24', 'TANGGAL BERLAKUNYA PERJANJIAN', '<div style="text-align: justify;"><span style="font-size: 1rem;">Perjanjian ini berlaku efektif terhitung sejak ditandatanganinya Perjanjian ini oleh wakil Para Pihak yang berwenang.</span></div>', 1, 2, 24, '2024-03-08 06:44:14', '2024-05-27 08:06:36'),
	(24, 'PASAL 25', 'LAMPIRAN - LAMPIRAN', '<ol><li style="text-align: justify; ">Lampiran I&nbsp; &nbsp; &nbsp; :  Dokumen-Dokumen Pengadaan</li><li style="text-align: justify;">Lampiran II&nbsp; &nbsp; &nbsp;:  Lingkup Perjanjian</li><li style="text-align: justify; ">Lampiran III&nbsp; &nbsp; :  Spesifikasi Teknis</li><li style="text-align: justify;">Lampiran IV&nbsp; &nbsp; :  Jadwal Penyerahan Barang</li><li style="text-align: justify;">Lampiran V&nbsp; &nbsp; &nbsp;:  Harga Barang</li><li style="text-align: justify;">Lampiran VI&nbsp; &nbsp; :  Pembayaran</li><li style="text-align: justify;">Lampiran VII&nbsp; &nbsp;:  Alamat Surat Menyurat</li></ol>', 1, 2, 25, '2024-03-08 06:45:31', '2024-12-08 13:23:15'),
	(25, 'PASAL 26', 'LAIN - LAIN', '<ol><li style="text-align: justify; ">Hal-hal yang belum diatur dan perubahan-perubahan dari Perjanjian ini, akan diselesaikan melalui kesepakatan atau perundingan kedua belah pihak dan yang akan dituangkan dalam suatu Addendum Perjanjian yang ditandatangani oleh kedua belah pihak serta merupakan bagian yang tidak dapat dipisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li><li style="text-align: justify; ">Segala ketentuan-ketentuan dan syarat-syarat dalam Perjanjian ini berlaku serta mengikat bagi pihak-pihak yang menandatangani, pengganti-penggantinya dan mereka yang memperoleh keuntungan dari padanya.</li><li style="text-align: justify;">Lampiran Perjanjian merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li></ol>', 1, 2, 26, '2024-03-08 06:45:31', '2024-12-08 13:23:55'),
	(26, 'PASAL 1', 'DEFINISI-DEFINISI', '<ol><li style="text-align: justify; "><b>Perjanjian</b> adalah Perjanjian ini yang dibuat dan ditandatangani antara Para Pihak, termasuk seluruh lampirannya dan setiap perubahan-perubahannya.</li><li style="text-align: justify;"><b>Barang</b> adalah barang berupa xyzxyz yang harus diadakan dan dipasok oleh PIHAK KEDUA sesuai Spesifikasi Teknis.</li><li style="text-align: justify;"><b>Spesifikasi Teknis</b> adalah Spesifikasi Teknis Barang yang sebagaimana rinciannya yang dimaksud dalam Pasal 4 Perjanjian ini.</li><li style="text-align: justify;"><b>Bulan dan Hari</b> adalah bulan dan hari terkait yang tercantum dalam kalender Masehi.</li><li style="text-align: justify; "><b>Tanggal Berlakunya Perjanjian</b> adalah tanggal dimana semua ketentuan yang terdapat pada Pasal 23 Perjanjian ini terpenuhi.</li><li style="text-align: justify;"><b>Surat Penerimaan Barang ("SPB")</b> adalah pernyataan tertulis bertanggal dan diterbitkan oleh PIHAK KESATU yang menyatakan bahwa barang telah diserahkan dan diterima oleh PIHAK KESATU sesuai dengan Perjanjian.</li><li style="text-align: justify;"><b>Jaminan Mutu</b> adalah jaminan dari PIHAK KEDUA untuk senantiasa menjaga kualitas barang selama masa tertentu sebagaimana diatur dalam Pasal 13 Perjanjian ini.</li><li style="text-align: justify;"><b>Pelindungan Data Pribadi </b>adalah keseluruhan upaya untuk melindungi Data Pribadi dalam rangkaian pemrosesan Data Pribadi guna menjamin hak konstitusional subjek Data Pribadi.</li><li style="text-align: justify;"><b>Undang-Undang Pelindungan Data Pribadi </b>adalah Undang-Undang No. 27 Tahun 2022 tentang Pelindungan Data Pribadi sebagaimana diubah dari waktu ke waktu.</li><li style="text-align: justify;"><b>Data Pribadi </b>adalah data tentang orang perseorangan yang teridentifikasi atau dapat diidentifikasi secara tersendiri atau dikombinasi dengan informasi lainnya baik secara langsung maupun tidak langsung melalui sistem elektronik atau non-elektronik.</li></ol>', 2, 1, 1, '2024-03-08 07:29:06', '2024-12-06 08:09:34'),
	(29, 'PASAL 2', 'KETENTUAN-KETENTUAN UMUM', '<ol><li style="text-align: justify; ">Apabila suatu ketentuan Perjanjian ini atau bagian dari padanya dianggap batal, tidak sah atau tidak dapat diberlakukan berdasarkan peraturan perundang-undangan yang berlaku terhadap mana ketentuan tersebut tunduk, maka ketentuan dimaksud dianggap batal, tidak sah atau tidak dapat diberlakukan dengan cara apapun, tidak berpengaruh pada atau mengurangi berlakunya bagian lain dari ketentuan tersebut atau ketentuan-ketentuan lainnya dari Perjanjian ini.</li><li style="text-align: justify;">Kelalaian salah satu Pihak dalam melaksanakan, dan keterlambatan satu Pihak melaksanakan hak berdasarkan Perjanjian ini, tidak berlaku sebagai pembebasan atau pengesampingan dari setiap pelaksanaan keseluruhan atau sebagian dari hak berdasarkan Perjanjian ini tidak mencegah pelaksanaan lain atau pelaksanaan selanjutnya dari hak tersebut.</li><li style="text-align: justify;">Perjanjian ini berlaku untuk kepentingan dan mengikat Para Pihak, para pengganti dan para penerima hak yang diijinkan masing-masing Pihak.</li><li style="text-align: justify;">Perjanjian ini menggantikan dan mengesampingkan semua dokumen, perjanjian, kesepakatan, atau pemahaman yang pernah dibuat sebelumnya, baik secara tertulis maupun lisan, yang berkaitan dengan objek dan ketentuan-ketentuan yang diatur dalam Perjanjian ini.</li></ol>', 2, 1, 2, '2024-03-08 07:29:23', '2024-12-06 08:13:08'),
	(30, 'PASAL 3', 'LINGKUP PERJANJIAN', '<div style="text-align: justify;"><span style="font-size: 1rem;">Lingkup Perjanjian sebagaimana tercantum pada Lampiran II Perjanjian ini.</span></div>', 2, 1, 3, '2024-03-08 07:41:32', '2024-05-27 08:18:36'),
	(31, 'PASAL 4', 'SPESIFIKASI TEKNIS', '<div style="text-align: justify;"><span style="font-size: 1rem;">Spesifikasi teknis Barang sebagaimana tercantum dalam Lampiran III Perjanjian ini.</span></div>', 2, 1, 4, '2024-03-08 07:41:32', '2024-12-06 08:13:42'),
	(32, 'PASAL 5', 'JADWAL PENYERAHAN BARANG', '<div style="text-align: justify;"><span style="font-size: 1rem;">Jadwal penyerahan barang sebagaimana dimaksud dalam Lampiran IV Perjanjian ini.</span></div>', 2, 1, 5, '2024-03-08 07:41:32', '2024-05-27 08:19:23'),
	(33, 'PASAL 6', 'PERUBAHAN JADWAL PENYERAHAN BARANG', '<ol><li style="text-align: justify; ">Jadwal penyerahan Barang dimaksud Pasal 5 Perjanjian ini dapat berubah sewaktu-waktu sesuai permintaan PIHAK KESATU, yang mana permintaan tersebut dibuat secara tertulis oleh dan dari PIHAK KESATU kepada PIHAK KEDUA, yang selanjutnya diperlukan adanya persetujuan dari PIHAK KEDUA dengan tetap memperhatikan situasi dan kondisi proses produksi.</li><li style="text-align: justify; ">Perubahan dimaksud ayat (1) Pasal ini akan dituangkan dalam suatu Addendum Lampiran IV, yang merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.\r\n</li></ol>', 2, 1, 6, '2024-03-08 07:41:32', '2024-12-06 08:45:51'),
	(34, 'PASAL 7', 'HARGA BARANG', 'Harga Barang sebagaimana tercantum dalam Lampiran  V  Perjanjian ini.', 2, 1, 7, '2024-03-08 07:41:32', '2024-12-06 08:46:28'),
	(35, 'PASAL 8', 'PENERIMAAN DAN PEMERIKSAAN BARANG', '<ol><li style="text-align: justify; ">Barang yang telah diterima dari PIHAK KEDUA di gudang milik PIHAK KESATU di Karawang diperlakukan sebagai penerimaan sementara sampai dengan prosedur pemeriksaan Barang di PIHAK KESATU selesai dilaksanakan, tanpa mengurangi hak PIHAK KESATU untuk mempergunakan Barang tersebut dan masih berada dibawah tanggungjawab PIHAK KEDUA apabila ditemukan  kerusakan  dan atau ketidaksesuaian spesifikasinya.</li><li style="text-align: justify;">Selanjutnya terhadap Barang yang telah diterima di gudang milik PIHAK KESATU di Karawang tersebut pada ayat (1) Pasal ini akan dilakukan pemeriksaan oleh PIHAK KESATU sesuai dengan prosedur pemeriksaan yang berlaku di PIHAK KESATU.</li><li style="text-align: justify;">Apabila Barang yang oleh PIHAK KESATU dinyatakan tidak baik atau tidak sesuai dengan Spesifikasi Teknis, maka PIHAK KEDUA harus segera mengambil Barang tersebut dalam waktu selambat-lambatnya 7 (tujuh) hari kalender setelah pemberitahuan oleh PIHAK KESATU dan harus menggantinya dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender sejak tanggal pemberitahuan oleh PIHAK KESATU atau dikembalikan pembayarannya oleh PIHAK KEDUA apabila terjadi ketidaksesuaian dengan Jaminan Mutu.</li><li style="text-align: justify; ">Barang pengganti seperti yang dimaksud ayat (3) Pasal ini harus diserahkan dalam keadaan lengkap, baik dan sesuai Spesifikasi Teknis yang mana terhadap Barang pengganti tersebut diberlakukan juga pemeriksaan seperti yang dimaksud ayat (2) Pasal ini.</li><li style="text-align: justify;">Barang yang oleh PIHAK KESATU dinyatakan baik dan sesuai dengan Spesifikasi Teknis atau persyaratan yang ditetapkan PIHAK KESATU akan dibuatkan SPB dan PIHAK KEDUA tetap harus mempertahankan Jaminan Mutu sebagaimana disepakati.</li><li style="text-align: justify;">Apabila PIHAK KEDUA melanggar ketentuan ayat (3) dan ayat (4) Pasal ini, maka PIHAK KESATU secara sepihak berhak membatalkan Surat Order Pembelian (<b>"SOP"</b>) dan atau Perjanjian ini tanpa adanya tuntutan dari PIHAK KEDUA maupun pihak ketiga lainnya atas pelaksanaan Perjanjian ini serta PIHAK KESATU berhak mengalihkan pelaksanaan Perjanjian ini pada pihak lain serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li></ol>', 2, 1, 8, '2024-03-08 07:41:32', '2024-12-06 08:52:38'),
	(36, 'PASAL 9', 'PEMBAYARAN', 'Pembayaran dari PIHAK KESATU kepada PIHAK KEDUA dilakukan sebagaimana tercantum dalam Lampiran VI Perjanjian ini.', 2, 1, 9, '2024-03-08 07:47:13', '2024-05-27 08:22:27'),
	(37, 'PASAL 10', 'PENGALIHAN KEPADA PIHAK KETIGA', '<ol><li style="text-align: justify; ">PIHAK KEDUA tidak diperbolehkan untuk mengalihkan pelaksanaan ruang lingkup Perjanjian ini, baik sebagian maupun keseluruhannya kepada pihak ketiga manapun kecuali diperbolehkan berdasarkan ketentuan Pasal 11 ini.</li><li style="text-align: justify;">PIHAK KEDUA hanya dapat melakukan pengalihan baik sebagian maupun keseluruhan kepada pihak ketiga atas dasar terjadinya hal tertentu dan/atau keadaan memaksa sebagaimana dimaksud Pasal 16 Perjanjian ini dan setelah mendapatkan persetujuan tertulis dari PIHAK KESATU.</li><li style="text-align: justify;">Tunduk kepada ketentuan ayat (2) di atas, maka :<ul><li style="text-align: justify;">PIHAK KEDUA bertanggungjawab penuh terhadap Jaminan Mutu.</li><li style="text-align: justify;">PIHAK KEDUA bertanggungjawab penuh dan akan memberikan ganti rugi kepada PIHAK KESATU apabila pengalihan kepada pihak ketiga mengalami kegagalan, kerusakan yang dapat merugikan PIHAK KESATU.</li><li style="text-align: justify;">PIHAK KEDUA harus mengawasi pelaksanaan oleh pihak ketiga atas ruang lingkup yang dialihkan tersebut dan melaporkan kepada PIHAK KESATU.</li><li style="text-align: justify;">PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan/gugatan dan klaim dari pihak ketiga manapun termasuk namun tidak terbatas dari pihak ketiga sehubungan dengan pelaksanaan pelaksanaan pengalihan tersebut.<br></li></ul></li><li style="text-align: justify; ">Apabila ketentuan ayat (1), ayat (2), ayat (3) Pasal 11 ini dilanggar oleh PIHAK KEDUA, maka PIHAK KESATU secara sepihak berhak membatalkan Perjanjian ini tanpa adanya tuntutan apapun dari PIHAK KEDUA, dan PIHAK KESATU berhak memberikan pelaksanaan pekerjaan tersebut kepada pihak lain serta apabila ada Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li></ol>', 2, 1, 10, '2024-03-08 07:47:13', '2024-12-06 08:57:52'),
	(38, 'PASAL 11', 'PESANAN TAMBAH KURANG', '<ol><li style="text-align: justify; ">PIHAK KESATU setiap saat dapat mengubah lingkup pelaksanaan Perjanjian seperti penambahan atau pengurangan pesanan Barang.</li><li style="text-align: justify; ">Jika perubahan dalam ayat (1) Pasal ini mengakibatkan penambahan atau pengurangan harga dan atau perubahan jadwal penyerahan barang pada SOP, maka akan dilakukan penyesuaian harga  dan atau jadwal penyerahan barang pada SOP, yang akan dituangkan dalam suatu surat perubahan SOP dan merupakan bagian yang tidak terpisahkan dari Perjanjian ini.</li><li style="text-align: justify;">Harga satuan pesanan tambah kurang dalam SOP tidak boleh melebihi dari harga satuan  yang telah disepakati sebelumnya sebagaimana tercantum dalam Pasal 7 Perjanjian ini.</li><li style="text-align: justify;">Pesanan tambah kurang baru dapat dilaksanakan oleh PIHAK KEDUA setelah  PIHAK KEDUA menerima Surat Pemberitahuan dari PIHAK KESATU mengenai perubahan pesanan tersebut.</li></ol>', 2, 1, 11, '2024-03-08 07:47:13', '2024-12-06 09:00:43'),
	(39, 'PASAL 12', 'JAMINAN MUTU BARANG', '<ol><li style="text-align: justify; ">PIHAK KEDUA memberikan Jaminan Mutu atas Barang dimana Barang yang dijual dan diserahkan kepada PIHAK KESATU adalah 100% (seratus persen) baru dan sesuai dengan ketentuan-ketentuan dan syarat-syarat yang ditetapkan dalam Perjanjian ini beserta Lampirannya, karena itu PIHAK KEDUA bertanggung jawab atas segala ketidaksesuaian mutu atas Barang termasuk tetapi tidak terbatas cacat tersembunyi ataupun kekurang sempurnaan dalam proses pembuatannya.</li><li style="text-align: justify;">Masa Jaminan Mutu (garansi) atas barang menurut Perjanjian ini adalah selama 12 (dua belas) bulan setelah keluarnya Surat Penerimaan Barang (SPB) dari Gudang PIHAK KESATU.</li><li style="text-align: justify;">Jaminan Mutu ini tidak berlaku bilamana dapat dibuktikan oleh PIHAK KEDUA bahwa ketidaksesuaian mutu atas Barang dimaksud Pasal ini disebabkan oleh karena kesalahan didalam pemakaian oleh PIHAK KESATU, namun yang terbukti bukan karena kesalahan dalam proses pembuatan ataupun juga karena kualitas bahan yang digunakan, hal mana harus dibuktikan oleh PIHAK KEDUA dan dapat meyakinkan PIHAK KESATU.</li><li style="text-align: justify; ">Dalam hal terjadi ketidaksesuaian mutu atas barang sebagaimana dimaksud Pasal ini maka PIHAK KESATU akan memberitahukan secara tertulis dalam jangka waktu selambat-lambatnya 7 (tujuh) hari kalender setelah ketidaksesuaian mutu atas Barang tersebut ditemukan, PIHAK KEDUA berkewajiban untuk memperbaiki dan atau menggantikannya dengan Barang yang baru dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender terhitung sejak tanggal pemberitahuan dari PIHAK KESATU, kecuali apabila PIHAK KEDUA dapat membuktikan bahwa ketidaksesuaian mutu atas Barang tersebut adalah terjadi karena sebab dimaksud ayat (3) Pasal ini.</li><li style="text-align: justify; ">Segala ongkos, biaya-biaya serta pengeluaran lain yang timbul karena penggantian dan atau perbaikan Barang tersebut menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 2, 1, 12, '2024-03-08 07:47:13', '2024-12-06 09:04:16'),
	(40, 'PASAL 13', 'JAMINAN HUKUM ATAS BARANG', '<ol><li style="text-align: justify; ">PIHAK KEDUA menjamin bahwa Barang yang diserahkan kepada PIHAK KESATU tidak diperoleh dari hal-hal yang bertentangan dengan hukum.</li><li style="text-align: justify;">PIHAK KEDUA menjamin bahwa Barang yang diserahkan berdasarkan Perjanjian ini tidak melanggar Hak Atas Kekayaan Intelektual (HAKI) atau hak lain yang dimiliki pihak ketiga.</li><li style="text-align: justify; ">Jika terjadi klaim atau tuntutan lainnya sehubungan dengan hal tersebut pada ayat (1) dan ayat (2) Pasal ini, PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan apapun dan dimanapun yang mungkin timbul serta PIHAK KEDUA dengan ini menyatakan akan mengambil segala tindakan hukum yang diperlukan termasuk mewakili didepan Pengadilan.</li><li style="text-align: justify;">Apabila klaim atau tuntutan pihak ketiga sebagaimana dimaksud ayat (1) dan (2) Pasal ini dikabulkan oleh Pengadilan atau oleh Badan Hukum apapun, maka PIHAK KEDUA menjamin bahwa barang tersebut tetap dapat dipergunakan dan menjadi milik PIHAK KESATU.</li></ol>', 2, 1, 13, '2024-03-08 07:47:13', '2024-12-06 09:07:50'),
	(41, 'PASAL 14', 'SANKSI', '<ol><li style="text-align: justify; ">Apabila jadwal penyerahan Barang sebagaimana dimaksud Pasal 5 Perjanjian ini terlampaui maka PIHAK KEDUA akan dikenakan sanksi berupa denda keterlambatan sebesar 1‰ (satu permil) setiap hari kalender keterlambatan dari harga Barang sebagaimana dimaksud Pasal 7 Perjanjian ini dengan batas maksimum denda keterlambatan sebesar 5% (lima persen) dari total harga Barang tersebut tidak termasuk Pajak Pertambahan Nilai (PPN), yang dapat dipotong secara sekaligus dari tagihan PIHAK KEDUA yang belum dibayar PIHAK KESATU.</li><li style="text-align: justify;">Apabila denda keterlambatan sudah mencapai batas maksimum sebagaimana dimaksud dalam ayat (1) Pasal ini atau waktu keterlambatan sudah mencapai 50 (lima puluh) hari kalender, maka PIHAK KEDUA dipandang tidak mampu untuk menyelesaikan Perjanjian ini, sehingga PIHAK KESATU berhak secara sepihak untuk memutuskan/membatalkan Perjanjian ini serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify; ">Segala kerugian nyata yang disebabkan oleh keterlambatan seperti yang dimaksud Pasal ini akan dibebankan kepada PIHAK KEDUA, kerugian tersebut termasuk tetapi tidak terbatas denda pihak ketiga terhadap PIHAK KESATU dan biaya-biaya lain yang timbul.</li><li style="text-align: justify;">Segala kerugian nyata yang diderita PIHAK KESATU akibat ketidak sesuaian mutu atas Barang sebagaimana dimaksud Pasal 13 Perjanjian ini, dan/atau kesalahan PIHAK KEDUA, termasuk tetapi tidak terbatas pada denda pihak ketiga terhadap PIHAK KESATU akan dibebankan kepada PIHAK KEDUA.</li><li style="text-align: justify;">Apabila ternyata PIHAK KEDUA tidak dapat memenuhi ketentuan-ketentuan Perjanjian ini atau menurut pertimbangan PIHAK KESATU bahwa PIHAK KEDUA dipandang tidak mampu memenuhi ketentuan-ketentuan dalam Perjanjian ini, maka PIHAK KESATU secara sepihak berhak memutuskan/membatalkan Perjanjian ini. Hal yang sama dapat pula dilakukan apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify;">Ketentuan sanksi sebagaimana dimaksud Pasal ini tidak berlaku apabila :<ul><li style="text-align: justify;">Suatu keterlambatan seperti yang dimaksud Pasal ini disebabkan karena perintah secara tertulis dari PIHAK KESATU kepada PIHAK KEDUA untuk menunda atau menghentikan sementara waktu pelaksanaan penyerahan Barang seperti yang dimaksud Pasal 5 Perjanjian ini.</li><li style="text-align: justify;">PIHAK KEDUA dapat membuktikan dan dapat meyakinkan PIHAK KESATU bahwa segala ketidak sesuaian mutu atas Barang seperti yang dimaksud Pasal 13 Perjanjian ini adalah di luar kesalahan PIHAK KEDUA.</li></ul></li></ol>', 2, 1, 14, '2024-03-08 07:47:13', '2024-12-06 09:11:42'),
	(42, 'PASAL 15', 'KEADAAN MEMAKSA', '<ol><li style="text-align: justify;">Yang dimaksud dengan Keadaan Memaksa adalah keadaan-keadaan yang disebabkan oleh kejadian-kejadian di luar kesalahan atau kekuasaan dari para pihak yang merintangi atau menghalangi pihak tersebut dalam menjalankan kewajibannya memenuhi Perjanjian ini, seperti :<ul><li style="text-align: justify;">Gempa bumi besar, angin topan, banjir besar, kebakaran besar, tanah longsor dan wabah penyakit.</li><li style="text-align: justify;">Pemogokan umum, huru-hara, sabotase, pemberontakan dan Kebijaksanaan Pemerintah di Bidang Moneter.</li><li style="text-align: justify;">Kejadian-kejadian lain di luar kekuasaan atau kemampuan dari para pihak.<br></li></ul></li><li style="text-align: justify;">Dalam hal Keadaan Memaksa yang dimaksud ayat (1) Pasal ini terjadi, maka pihak yang terkena Keadaan Memaksa wajib memberitahukan secara tertulis kepada pihak lainnya dalam jangka waktu 7 (tujuh) hari kalender dari sejak terjadinya Keadaan Memaksa dan diterangkan secara resmi oleh Pejabat yang berwenang mengeluarkannya.</li><li style="text-align: justify;">Kelalaian atau keterlambatan pihak yang terkena Keadaan Memaksa dalam menyampaikan pemberitahuannya sebagaimana dimaksud ayat (2) Pasal ini, mengakibatkan tidak diakuinya peristiwa sebagaimana dimaksud ayat (1) Pasal ini sebagai peristiwa Keadaan Memaksa oleh pihak lainnya.</li><li style="text-align: justify; ">Kejadian-kejadian dimaksud dalam ayat (1) Pasal ini dapat diperhitungkan sebagai perpanjangan waktu kewajiban yang harus dilaksanakan oleh pihak yang terkena Keadaan Memaksa apabila ketentuan dalam ayat (2) Pasal ini dipenuhi, dimana perpanjangan waktu tersebut akan dimusyawarahkan lebih lanjut oleh kedua belah pihak yang syarat-syarat dan ketentuan-ketentuan disetujui bersama yang dituangkan dalam suatu Perjanjian baru.</li><li style="text-align: justify;">Semua kerugian dan biaya-biaya yang diderita oleh salah satu pihak sebagai akibat Keadaan Memaksa bukan merupakan tanggung jawab pihak lainnya.</li></ol>', 2, 1, 15, '2024-03-08 07:55:29', '2024-10-17 04:22:00'),
	(43, 'PASAL 16', 'PEMBATALAN PERJANJIAN', '<ol><li>PIHAK KESATU berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi:<ul><li>Apabila PIHAK KEDUA terbukti tidak dapat menyelenggarakan Perjanjian yang dimaksud pada Pasal 4 dan 5 Perjanjian ini atau dipandang oleh PIHAK KESATU bahwa PIHAK KEDUA tidak mampu melaksanakan Perjanjian dimaksud Pasal 3 Perjanjian ini.</li><li>Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 9 ayat (6) Perjanjian ini.</li><li>Apabila PIHAK KEDUA terbukti melanggar ketentuan Pasal 11 ayat (2) dan (3) Perjanjian ini.</li><li>Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 16 ayat (2) dan (4) Perjanjian ini.</li><li>Apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang.<br></li></ul></li><li>PIHAK KEDUA berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi :<ul><li>Apabila PIHAK KESATU dinyatakan jatuh pailit oleh yang berwenang.</li><li>Apabila PIHAK KESATU gagal dalam memenuhi ketentuan Pasal 16 ayat (2) dan (4) Perjanjian ini.</li></ul></li><li>Untuk hal ihwal pembatalan Perjanjian dimaksud pada ayat (1) Pasal ini, Para Pihak dengan ini menyatakan sepakat dan berjanji untuk mengesampingkan berlakunya ketentuan Pasal 1266 dan Pasal 1267 Undang-undang Hukum Perdata terhadap Perjanjian ini, sehingga pembatalan Perjanjian ini dapat dilakukan secara sah cukup dengan surat pemberitahuan dari PIHAK KESATU kepada PIHAK KEDUA tanpa menunggu adanya keputusan dari Hakim serta dengan ini PIHAK KEDUA menyatakan melepaskan hak-hak yang timbul dari padanya apabila ada.</li><li>Dalam hal Perjanjian ini dibatalkan, maka Para Pihak secara bersama-sama mengadakan inventarisasi terhadap hak dan kewajiban yang ada dan apabila terdapat kekurangan atau kelebihan pembayaran oleh PIHAK KESATU, maka akan diadakan penambahan pembayaran oleh PIHAK KESATU atau pengembalian pembayaran oleh PIHAK KEDUA.</li><li>Dalam hal Perjanjian ini dibatalkan, maka PIHAK KEDUA dengan ini berjanji dan menyatakan membebaskan PIHAK KESATU dari segala tuntutan hukum, termasuk tuntutan dari pihak ketiga serta ganti rugi berupa apapun dan dari manapun karena batalnya Perjanjian ini, oleh karena itu sepenuhnya menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 2, 1, 16, '2024-03-08 07:55:29', '2024-12-06 09:16:51'),
	(44, 'PASAL 17', 'PENYELESAIAN PERSELISIHAN', '<ol><li style="text-align: justify; ">Apabila dikemudian hari terjadi perselisihan dalam penafsiran dan atau pelaksanaan ketentuan-ketentuan dari Perjanjian ini dan atau hal-hal lainnya maka Para Pihak telah sepakat dan berjanji untuk terlebih dahulu menyelesaikan secara musyawarah untuk mencapai mufakat.</li><li style="text-align: justify;">Bilamana cara musyawarah tersebut ayat (1) Pasal ini tidak dicapai kata sepakat dalam penyelesaian perselisihan, maka Para Pihak sepakat dan berjanji untuk menyelesaikan seluruh sengketa yang timbul dari Perjanjian ini kepada Badan Arbitrase Nasional Indonesia (BANI), untuk diselesaikan pada tingkat pertama dan terakhir menurut peraturan dan prosedur BANI. Arbitrase akan diselesaikan oleh 3 (tiga) orang Arbiter yang ditunjuk sebagai berikut:<ul><li style="text-align: justify;">Masing-masing dari Para Pihak harus menunjuk 1 (satu) Arbiter dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal suatu permintaan untuk Arbitrase telah dikeluarkan oleh pihak yang meminta atau para pihak lain telah bersama-sama setuju membawa perselisihan kepada Arbitrase dan kedua Arbiter yang ditunjuk secara bersama-sama akan menunjuk Arbiter ketiga yang akan menjadi Ketua Arbitrase.</li><li style="text-align: justify;">Apabila salah satu dari para pihak gagal menunjuk Arbiternya dalam jangka waktu sebagaimana dinyatakan di atas, Arbiter yang telah ditunjuk akan duduk sendiri sebagai Arbitrase dan memberikan Keputusan.</li><li style="text-align: justify;">Namun apabila kedua Arbiter gagal menunjuk Arbiter ketiga dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal penunjukan kedua Arbiter, maka Ketua BANI atau Pejabat BANI yang berwenang akan menunjuk Arbiter ketiga sebagai Ketua Arbiter atas permintaan salah satu pihak.<br></li></ul></li><li style="text-align: justify;">Para pihak harus menanggung biaya Arbitrase secara sama rata dan proses Arbitrase harus dilangsungkan di Jakarta.</li><li style="text-align: justify;">Kecuali dalam ayat (2) sub b. Pasal ini, Keputusan Badan Arbitrase diambil berdasarkan suara terbanyak dan bersifat mengikat kedua belah pihak terhadap para pihak.</li><li style="text-align: justify; ">Para pihak telah sepakat dan berjanji untuk secara tegas menentukan tidak ada banding atau penghentian pelaksanaan yang diajukan ke Pengadilan atas Keputusan Badan Arbitrase dan para pihak tidak akan menolak atau menentang pelaksanaan keputusan yang dilakukan oleh pihak untuk keuntungan siapa keputusan Badan Arbitrase telah diberikan.</li><li style="text-align: justify;">Tiada satu pihak berhak untuk memulai atau melakukan tindakan di Pengadilan terhadap segala masalah dalam sengketa sampai dengan masalah tersebut telah diputuskan sebagaimana diatur di sini, kecuali untuk pelaksanaan keputusan Badan Arbitrase.</li><li style="text-align: justify;">Selama proses Arbitrase dan sampai Arbitrase memberikan keputusannya, para pihak setuju untuk terus melaksanakan semua kewajibannya masing-masing berdasarkan Perjanjian ini tanpa berprasangka atau menduga atas putusan akhir yang diambil oleh para Arbiter tersebut.</li><li style="text-align: justify;">Para pihak setuju memberlakukan penunjukan tidak akan berakhir pada tanggal setelah 6 (enam) bulan kalender sejak tanggal penunjukannya dan mandat kepada Arbitrase (wasit-wasit) sebagaimana yang ditetapkan sesuai dengan keputusan ini, akan tetap berlangsung sampai keputusan telah diambil oleh Badan Arbitrase.</li><li style="text-align: justify;">Keputusan Badan Arbitrase dapat dilaksanakan di setiap Pengadilan dimanapun yang mempunyai yurisdiksi yang berwenang terhadap masing-masing para pihak atau harta kekayaannya.</li></ol>', 2, 1, 17, '2024-03-08 07:55:29', '2024-10-17 04:27:16'),
	(45, 'PASAL 18', 'KETENTUAN MENJAGA RAHASIA', '<ol><li style="text-align: justify; ">Para Pihak sepakat melakukan usaha-usaha mereka yang terbaik untuk menjaga kerahasiaan Informasi sehubungan dengan Perjanjian ini dan Para Pihak harus memastikan direktur-direktur, pegawai-pegawai, agen-agen atau pembantu-pembantu mereka tidak akan mengungkapkan informasi, data, dokumentasi dan pengetahuan kepada Pihak Ketiga tanpa persetujuan tertulis dari pihak yang lain, tidak juga akan menerbitkan informasi, data, dokumentasi dan pengetahuan dalam bentuk cetakan, kaset, disket, disk atau bentuk-bentuk lain, kecuali sepanjang tindakan dilakukan sebagai laporan kepada instansi pemerintah terkait sebagaimana diperlukan oleh undang-undang.</li><li style="text-align: justify;">Kecuali informasi yang teridentifikasi dibuka oleh pihak pemberi informasi kepada pihak lain, bila dibuka secara tertulis berlabel “<i>proprietary</i>” atau “<i>confidential</i>” atau setiap label yang mempunyai arti yang semacam, atau bila dibuka secara lisan, yang harus dituangkan dalam tulisan dalam jangka waktu 30 (tiga puluh) hari dan berlabel ”<i>proprietary</i>” atau “<i>confidential</i>” atau setiap label yang memiliki arti yang semacam (informasi rahasia) tetap menjadi milik pihak pemberi informasi.</li><li style="text-align: justify;">Kecuali untuk hak-hak khusus yang diberikan oleh Perjanjian ini, pihak penerima informasi tidak boleh menggunakan setiap informasi rahasia untuk kepentingannya sendiri. Pihak penerima informasi harus menggunakan tingkatan pemeliharaan tertinggi yang wajar secara komersial untuk memproteksi informasi rahasia dari pihak pemberi informasi. Pihak penerima informasi tidak boleh membuka informasi rahasia kepada Pihak Ketiga manapun tanpa persetujuan tertulis yang tegas dari pihak pemberi informasi.</li><li style="text-align: justify;">Informasi rahasia tidak mencakup informasi:<ul><li style="text-align: justify;">Yang tersedia kepada pihak publik selain dari pada karena wanprestasi karena Perjanjian ini.</li><li style="text-align: justify;">Yang secara sah diterima dari Pihak Ketiga yang tidak melanggar kewajiban kerahasiaan.</li><li style="text-align: justify;">Yang secara independen dikembangkan oleh pihak penerima informasi tanpa akses pada informasi rahasia.</li><li style="text-align: justify;">Yang diberitahukan kepada pihak penerima informasi pada waktu dilangsungkan keterbukaan; atau </li><li style="text-align: justify;">Yang dibuat sesuai dengan ketentuan hukum atau perintah pengadilan, dengan ketentuan pihak pemberi informasi diberikan pengetahuan yang wajar mengenai ketentuan hukum atau perintah pengadilan tersebut dan kesempatan untuk mencabut untuk mengecualikan atau membatasi perbuatan tersebut.</li></ul></li><li style="text-align: justify;">Pihak penerima informasi setuju untuk menghentikan penggunaan setiap dan semua bahan yang memuat informasi rahasia kepada pihak pemberi informasi ketika diminta.<br></li></ol>', 2, 1, 18, '2024-03-08 07:55:29', '2024-12-06 09:18:52'),
	(46, 'PASAL 19', 'HUKUM YANG BERLAKU', '<ol><li>Perjanjian ini tunduk dan berada di bawah ketentuan hukum Republik Indonesia.</li><li>PIHAK KEDUA harus mematuhi semua peraturan perundang-undangan dan kebijakan pemerintah yang berlaku di Indonesia.</li></ol>', 2, 1, 19, '2024-03-08 07:55:29', '2024-10-11 07:49:02'),
	(47, 'PASAL 20', 'PELINDUNGAN DATA PRIBADI', '<div style="text-align: justify; ">Para Pihak dengan ini mengakui dan memahami setiap kewajiban Para Pihak dalam upaya Pelindungan Data Pribadi sesuai dengan ketentuan yang berlaku, antara lain :</div><ol><li style="text-align: justify; ">Memproses Data Pribadi sesuai Undang-Undang Perlindungan Data Pribadi dan ketentuan dalam Peraturan Perundang-undangan lainnya.</li><li style="text-align: justify; ">Hanya memproses Data Pribadi apabila dan hanya sejauh diperlukan agar dapat melaksanakan kewajiban berdasarkan Perjanjian.</li><li><div style="text-align: justify;"><span style="font-size: 1rem;">Tidak mengungkapkan Data Pribadi kepada pihak ketiga mana pun selain:</span></div><ul><li style="text-align: justify; "><span style="font-size: 1rem;">Karyawan, direksi, afiliasi berdasarkan kebutuhan (need-to know) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini;</span></li><li style="text-align: justify; ">Subkontraktor atau penasehat professional yang diizinkan secara tertulis oleh Para Pihak untuk memproses Data Pribadi berdasarkan kebutuhan (need-to know basis) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini; atau&nbsp;</li><li style="text-align: justify; ">Sejauh diperlukan oleh peraturan perundang-undangan yang berlaku, namun tetap memperhatikan dan mematuhi Undang-Undang Perlindungan Data. Dalam hal tersebut, Pihak yang berkepentingan harus memberikan pemberitahuan tertulis kepada Pihak lainnya untuk mengungkapkan Data Pribadi (sejauh diizinkan oleh peraturan perundang-undangan yang berlaku) segera mungkin setelah mengetahui persyaratan tersebut.</li></ul></li><li style="text-align: justify; ">Memastikan bahwa personilnya yang memproses Data Pribadi melaksanakan hal tersebut dan tetap patuh terhadap kewajiban kerahasiaan; dan</li><li style="text-align: justify; ">Melaksanakan dan mempertahankan tindakan atau langkah administratif, teknis dan organisasi yang cukup:<ul><li style="text-align: justify; ">Untuk menjaga keamanan Data Pribadi; dan</li><li style="text-align: justify; ">Untuk mencegah penghapusan tidak sah atau tidak disengaja, perubahan tidak sah, menyalin, mengakses atau menggunakan, pemalsuan, pencurian, kehilangan atau kesalahan teknis sehubungan dengan Data Pribadi.<br></li></ul></li><li style="text-align: justify; ">Para Pihak bertanggung jawab atas kerugian terhadap pelanggaran ketentuan terkait Data Pribadi yang diakibatkan oleh kelalaian personilnya serta akan bertanggung jawab penuh, termasuk namun tidak terbatas pada segala klaim, tuntutan, gugatan, sengketa, dan/atau ganti kerugian yang mungkin timbul dari pelanggaran ketentuan terkait Data Pribadi.<br></li></ol>', 2, 1, 20, '2024-03-08 07:55:29', '2024-12-06 09:20:15'),
	(48, 'PASAL 21', 'LARANGAN PEMBERIAN HADIAH DAN KOMISI', '<ol><li style="text-align: justify; ">PIHAK KEDUA dilarang untuk menerima penawaran atau menyetujui pemberian hadiah, komisi, potongan atau bentuk-bentuk lain yang sejenis dari Direksi, staff/karyawan dari PIHAK KESATU untuk tujuan ditandatanganinya dan/atau pelaksanaan Perjanjian ini.</li><li style="text-align: justify;">Pelanggaran terhadap ayat 1 Pasal ini oleh PIHAK KEDUA atau karyawannya atau pihak lain yang bekerja untuk PIHAK KEDUA dapat mengakibatkan pembatalan Perjanjian ini oleh PIHAK KESATU, dan biaya yang timbul dari pembatalan tersebut akan menjadi tanggung jawab PIHAK KEDUA, dan PIHAK KEDUA akan dieliminasi sebagai mitra bisnis PIHAK KESATU.</li><li style="text-align: justify;">Pelanggaran dari setiap ketentuan dalam Pasal ini akan mengakibatkan gugatan pidana terhadap PIHAK KEDUA. Dalam hal terjadi penindaklanjutan atas adanya tindakan penerimaan komisi atau hadiah yang berpotensi merugikan PIHAK KESATU, semua biaya, ongkos dan kerugian yang timbul akan menjadi tanggung jawab PIHAK KEDUA. </li></ol>', 2, 1, 21, '2024-03-08 07:58:04', '2024-05-27 08:31:39'),
	(49, 'PASAL 22', 'TANGGAL BERLAKUNYA PERJANJIAIN', 'Perjanjian ini berlaku efektif terhitung sejak ditandatanganinya Perjanjian ini oleh wakil Para Pihak yang berwenang.', 2, 1, 22, '2024-03-08 07:58:04', '2024-05-27 08:31:55'),
	(50, 'PASAL 23', 'LAMPIRAN - LAMPIRAN', '<ol><li style="text-align: justify; ">Lampiran I&nbsp; &nbsp; &nbsp; &nbsp;:&nbsp; Dokumen-Dokumen Pengadaan</li><li style="text-align: justify;">Lampiran II&nbsp; &nbsp; &nbsp; :&nbsp; Lingkup Perjanjian</li><li style="text-align: justify; ">Lampiran III&nbsp; &nbsp; &nbsp;:&nbsp; Spesifikasi Teknis</li><li style="text-align: justify;">Lampiran IV&nbsp; &nbsp; &nbsp;:&nbsp; Jadwal Penyerahan Barang</li><li style="text-align: justify;">Lampiran V&nbsp; &nbsp; &nbsp; :&nbsp; Harga Barang</li><li style="text-align: justify;">Lampiran VI&nbsp; &nbsp; &nbsp;:&nbsp; Pembayaran</li><li style="text-align: justify;">Lampiran VII&nbsp; &nbsp; :&nbsp; Alamat Surat Menyurat\r\n</li></ol>', 2, 1, 23, '2024-03-08 07:58:04', '2024-10-28 07:41:04'),
	(51, 'PASAL 24', 'LAIN - LAIN', '<ol><li style="text-align: justify; ">Hal-hal yang belum diatur dan perubahan-perubahan dari Perjanjian ini, akan diselesaikan melalui kesepakatan atau perundingan kedua belah pihak dan yang akan dituangkan dalam suatu Addendum Perjanjian yang ditandatangani oleh kedua belah pihak serta merupakan bagian yang tidak dapat dipisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li><li style="text-align: justify;">Segala ketentuan-ketentuan dan syarat-syarat dalam Perjanjian ini berlaku serta mengikat bagi pihak-pihak yang menandatangani, pengganti-penggantinya dan mereka yang memperoleh keuntungan dari padanya.</li><li style="text-align: justify;">Lampiran Perjanjian merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li></ol>', 2, 1, 24, '2024-03-08 07:58:04', '2024-05-27 08:32:25'),
	(60, 'PASAL 7', 'MASA BERLAKU PERJANJIAN', '<p>Masa berlaku Perjanjian ini terhitung sejak tanggal 27 Februari 2024 sampai dengan 31 Desember 2024, kecuali Para Pihak sepakat untuk mengakhiri atau memperpanjang masa berlakunya Perjanjian ini.<br></p>', 1, 2, 7, '2024-05-27 07:35:52', '2024-05-27 07:35:52'),
	(61, 'PASAL 1', 'DEFINISI - DEFINISI', '<ol><li style="text-align: justify; "><b>Perjanjian</b> adalah Perjanjian ini yang dibuat dan ditandatangani antara Para Pihak, termasuk seluruh lampirannya dan setiap perubahan-perubahannya.</li><li style="text-align: justify;"><b>Barang</b> adalah barang berupa xyzxyz yang harus diadakan dan dipasok oleh PIHAK KEDUA sesuai Spesifikasi Teknis.</li><li style="text-align: justify;"><b>Spesifikasi Teknis</b> adalah spesifikasi teknis Barang sebagaimana rinciannya yang dimaksud dalam Pasal 4 Perjanjian ini.</li><li style="text-align: justify;"><b>Bulan dan Hari</b> adalah bulan dan hari terkait yang tercantum dalam kalender Masehi.</li><li style="text-align: justify;"><b>Tanggal Berlakunya Perjanjian</b> adalah tanggal dimana semua ketentuan yang terdapat pada Pasal 23 Perjanjian ini terpenuhi.</li><li style="text-align: justify;"><b>Surat Penerimaan Barang ("SPB")</b> adalah pernyataan tertulis bertanggal dan diterbitkan oleh PIHAK KESATU yang menyatakan bahwa barang telah diserahkan dan diterima oleh PIHAK KESATU sesuai dengan Perjanjian.</li><li style="text-align: justify; "><b>Jaminan Mutu</b> adalah jaminan dari PIHAK KEDUA untuk senantiasa menjaga kualitas barang selama masa tertentu sebagaimana diatur dalam Pasal 13 Perjanjian ini.</li><li style="text-align: justify; "><b>Jaminan Pelaksanaan </b>adalah sebagaimana rinciannya yang dimaksud dalam Pasal 8 Perjanjian ini.</li><li style="text-align: justify; "><b>Pelindungan Data Pribadi </b>adalah keseluruhan upaya untuk melindungi Data Pribadi dalam rangkaian pemrosesan Data Pribadi guna menjamin hak konstitusional subjek Data Pribadi.</li><li style="text-align: justify; "><b>Undang-Undang Pelindungan Data Pribadi </b>adalah Undang-Undang No. 27 Tahun 2022 tentang Pelindungan Data Pribadi sebagaimana diubah dari waktu ke waktu.</li><li style="text-align: justify; "><b>Data Pribadi </b>adalah data tentang orang perseorangan yang teridentifikasi atau dapat diidentifikasi secara tersendiri atau dikombinasi dengan informasi lainnya baik secara langsung maupun tidak langsung melalui sistem elektronik atau non-elektronik.</li></ol>', 1, 1, 1, '2024-05-27 08:35:34', '2024-12-06 02:14:00'),
	(62, 'PASAL 2', 'KETENTUAN - KETENTUAN UMUM', '<ol><li style="text-align: justify; ">Apabila suatu ketentuan Perjanjian ini atau bagian dari padanya dianggap batal, tidak sah atau tidak dapat diberlakukan berdasarkan peraturan perundang-undangan yang berlaku terhadap mana ketentuan tersebut tunduk, maka ketentuan dimaksud dianggap batal, tidak sah atau tidak dapat diberlakukan dengan cara apapun, tidak berpengaruh pada atau mengurangi berlakunya bagian lain dari ketentuan tersebut atau ketentuan-ketentuan lainnya dari Perjanjian ini.</li><li style="text-align: justify; ">Kelalaian salah satu Pihak dalam melaksanakan, dan keterlambatan satu Pihak melaksanakan hak berdasarkan Perjanjian ini, tidak berlaku sebagai pembebasan atau pengesampingan dari setiap pelaksanaan keseluruhan atau sebagian dari hak berdasarkan Perjanjian ini tidak mencegah pelaksanaan lain atau pelaksanaan selanjutnya dari hak tersebut.</li><li style="text-align: justify;">Perjanjian ini berlaku untuk kepentingan dan mengikat Para Pihak, para pengganti dan para penerima hak yang diijinkan masing-masing Pihak.</li><li style="text-align: justify;">Perjanjian ini menggantikan dan mengesampingkan semua dokumen, perjanjian, kesepakatan, atau pemahaman yang pernah dibuat sebelumnya, baik secara tertulis maupun lisan, yang berkaitan dengan objek dan ketentuan-ketentuan yang diatur dalam Perjanjian ini.</li></ol>', 1, 1, 2, '2024-05-27 08:37:32', '2024-12-06 02:37:27'),
	(63, 'PASAL 3', 'LINGKUP PERJANJIAN', '<p>Lingkup Perjanjian sebagaimana tercantum pada Lampiran II Perjanjian ini.<br></p>', 1, 1, 3, '2024-05-27 08:38:21', '2024-05-27 08:38:21'),
	(64, 'PASAL 4', 'SPESIFIKASI TEKNIS', '<p>Spesifikasi teknis Barang sebagaimana tercantum dalam Lampiran III Perjanjian ini.<br></p>', 1, 1, 4, '2024-05-27 08:38:54', '2024-12-06 02:38:40'),
	(65, 'PASAL 5', 'JADWAL PENYERAHAN BARANG', '<p style="text-align: justify; ">Jadwal penyerahan Barang sebagaimana dimaksud dalam Lampiran IV Perjanjian ini.<br></p>', 1, 1, 5, '2024-05-27 08:40:50', '2024-12-06 02:39:23'),
	(66, 'PASAL 6', 'PERUBAHAN JADWAL PENYERAHAN BARANG', '<ol><li style="text-align: justify; ">Jadwal penyerahan Barang dimaksud Pasal 5 Perjanjian ini dapat berubah sewaktu-waktu sesuai permintaan PIHAK KESATU, yang mana permintaan tersebut dibuat secara tertulis oleh dan dari PIHAK KESATU kepada PIHAK KEDUA, yang selanjutnya diperlukan adanya persetujuan dari PIHAK KEDUA dengan tetap memperhatikan situasi dan kondisi proses produksi.</li><li style="text-align: justify; ">Perubahan dimaksud ayat (1) Pasal ini akan dituangkan dalam suatu Addendum Lampiran IV, yang merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li></ol>', 1, 1, 6, '2024-05-27 08:42:29', '2024-12-06 02:41:20'),
	(67, 'PASAL 7', 'HARGA BARANG', '<p>Harga barang sebagaimana tercantum dalam Lampiran V Perjanjian ini.</p>', 1, 1, 7, '2024-05-27 08:43:01', '2024-05-27 08:43:01'),
	(68, 'PASAL 8', 'JAMINAN PELAKSANAAN', '<ol><li style="text-align: justify; ">PIHAK KEDUA harus menyerahkan kepada PIHAK KESATU suatu Jaminan Pelaksanaan (<i>Performance Bond</i>) berupa garansi bank yang diterbitkan oleh suatu Bank BUMN/BUMD sebesar 5% (lima persen) dari total harga Barang secara keseluruhan seperti dimaksud Pasal 7 Perjanjian ini.</li><li style="text-align: justify; ">Jaminan Pelaksanaan yang dimaksud ayat (1) Pasal ini harus mempunyai masa berlaku sampai dengan pelaksanaan Perjanjian selesai secara 100% (seratus persen) yang dinyatakan dengan SPB.</li><li style="text-align: justify; ">Apabila Jaminan Pelaksanaan dimaksud ayat (1) Pasal ini akan habis masa berlakunya sementara pelaksanaan Perjanjian belum selesai, maka PIHAK KEDUA berkewajiban untuk memperpanjang masa berlaku Jaminan Pelaksanaan tersebut selambat-lambatnya dalam waktu 7 (tujuh) hari kalender sebelum habis masa berlakunya Jaminan Pelaksanaan tersebut.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA lalai ataupun sengaja tidak menyerahkan Jaminan Pelaksanaan yang telah diperpanjang masa berlakunya dalam waktu paling lambat 5 (lima) hari kalender sebelum Jaminan Pelaksanaan yang dimaksud dalam ayat (1) Pasal ini jatuh tempo, maka PIHAK KESATU berhak secara sepihak tanpa perlu adanya pemberitahuan terlebih dahulu kepada PIHAK KEDUA untuk mencairkan Jaminan Pelaksanaan tersebut pada saat berakhirnya Jaminan Pelaksanaan dan PIHAK KESATU berhak pula untuk menahan pembayarannya serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA lalai memenuhi kewajibannya sesuai dengan syarat-syarat dan ketentuan-ketentuan dalam Perjanjian ini dan atau Perjanjian ini dibatalkan karena kesalahan PIHAK KEDUA, maka Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify; ">Jaminan Pelaksanaan dimaksud ayat (1) dan (2) Pasal ini akan dikembalikan oleh PIHAK KESATU kepada PIHAK KEDUA apabila pelaksanaan Perjanjian ini telah selesai secara 100% (seratus persen) yang dinyatakan dengan SPB.</li></ol>', 1, 1, 8, '2024-05-27 08:45:59', '2024-12-06 02:47:17'),
	(69, 'PASAL 9', 'PENERIMAAN DAN PEMERIKSAAN BARANG', '<ol><li style="text-align: justify; ">Barang yang telah diterima dari PIHAK KEDUA di gudang milik PIHAK KESATU di Karawang diperlakukan sebagai penerimaan sementara sampai dengan prosedur pemeriksaan Barang di PIHAK KESATU selesai dilaksanakan, tanpa mengurangi hak PIHAK KESATU untuk mempergunakan Barang tersebut dan masih berada dibawah tanggungjawab PIHAK KEDUA apabila ditemukan kerusakan dan atau ketidaksesuaian spesifikasinya.</li><li style="text-align: justify; ">Selanjutnya terhadap Barang yang telah diterima di gudang milik PIHAK KESATU di Karawang tersebut pada ayat (1) Pasal ini dilakukan pemeriksaan oleh PIHAK KESATU sesuai dengan prosedur pemeriksaan yang berlaku di PIHAK KESATU.</li><li style="text-align: justify; ">Apabila Barang yang oleh PIHAK KESATU dinyatakan tidak baik atau tidak sesuai dengan Spesifikasi Teknis, maka PIHAK KEDUA harus segera mengambil Barang tersebut dalam waktu selambat-lambatnya 7 (tujuh) hari kalender setelah tanggal pemberitahuan oleh PIHAK KESATU dan harus menggantinya dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender sejak tanggal pemberitahuan oleh PIHAK KESATU atau dikembalikan pembayarannya oleh PIHAK KEDUA apabila terjadi ketidaksesuaian dengan Jaminan Mutu.</li><li style="text-align: justify; ">Barang pengganti seperti yang dimaksud ayat (3) Pasal ini harus diserahkan dalam keadaan lengkap, baik dan sesuai Spesifikasi Teknis yang mana terhadap Barang pengganti tersebut diberlakukan juga pemeriksaan seperti yang dimaksud ayat (2) Pasal ini.</li><li style="text-align: justify; ">Barang yang oleh PIHAK KESATU dinyatakan baik dan sesuai dengan Spesifikasi Teknis atau persyaratan yang ditetapkan PIHAK KESATU akan dibuatkan SPB dan PIHAK KEDUA tetap harus mempertahankan Jaminan Mutu sebagaimana disepakati.</li><li style="text-align: justify; ">Apabila PIHAK KEDUA melanggar ketentuan ayat (3) dan (4) Pasal ini, maka PIHAK KESATU secara sepihak berhak membatalkan Surat Order Pembelian (<b>"SOP"</b>) dan atau Perjanjian ini tanpa adanya tuntutan dari PIHAK KEDUA maupun pihak ketiga lainnya atas pelaksanaan Perjanjian ini serta PIHAK KESATU berhak mengalihkan pelaksanaan Perjanjian ini pada pihak lain serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li></ol>', 1, 1, 9, '2024-05-27 08:49:01', '2024-12-06 02:55:18'),
	(70, 'PASAL 10', 'PEMBAYARAN', '<p>Pembayaran&nbsp; dari PIHAK KESATU kepada PIHAK KEDUA dilakukan sebagaimana tercantum dalam Lampiran VI Perjanjian ini.</p>', 1, 1, 10, '2024-05-27 08:49:51', '2024-05-27 08:49:51'),
	(71, 'PASAL 11', 'PENGALIHAN KEPADA PIHAK KETIGA', '<ol><li style="text-align: justify; ">PIHAK KEDUA tidak diperbolehkan untuk mengalihkan pelaksanaan ruang lingkup Perjanjian ini, baik sebagian maupun keseluruhannya kepada pihak ketiga manapun kecuali diperbolehkan berdasarkan ketentuan Pasal 11 ini.</li><li style="text-align: justify; ">PIHAK KEDUA hanya dapat melakukan pengalihan baik sebagian maupun keseluruhan kepada pihak ketiga atas dasar terjadinya hal tertentu dan/atau memaksa sebagaimana dimaksud Pasal 16 Perjanjian ini dan setelah mendapatkan persetujuan tertulis dari PIHAK KESATU.</li><li style="text-align: justify; ">Tunduk kepada ketentuan ayat (2) di atas, maka :<ul><li style="text-align: justify;">PIHAK KEDUA bertanggungjawab penuh terhadap Jaminan Mutu.</li><li style="text-align: justify;">PIHAK KEDUA bertanggungjawab penuh dan akan memberikan ganti rugi kepada PIHAK KESATU apabila pengalihan kepada pihak ketiga tersebut mengalami kegagalan, kerusakan yang dapat merugikan PIHAK KESATU.</li><li style="text-align: justify;">PIHAK KEDUA harus mengawasi pelaksanaan oleh pihak ketiga atas ruang lingkup yang dialihkan tersebut dan melaporkan kepada PIHAK KESATU.</li><li style="text-align: justify;">PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan/gugatan dan klaim dari pihak ketiga manapun termasuk namun tidak terbatas dari pihak ketiga sehubungan dengan pelaksanaan pengalihan tersebut.</li></ul></li><li style="text-align: justify;"><span style="font-size: 1rem;">Apabila ketentuan ayat (1), ayat (2) dan ayat (3) Pasal 11 ini dilanggar oleh PIHAK KEDUA, maka&nbsp;</span>PIHAK KESATU secara sepihak berhak membatalkan Perjanjian ini tanpa adanya tuntutan apapun dari PIHAK KEDUA, dan PIHAK KESATU berhak memberikan pelaksanaan pekerjaan tersebut kepada pihak lain serta apabila ada Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li></ol>', 1, 1, 11, '2024-05-27 08:54:41', '2024-12-06 03:02:14'),
	(72, 'PASAL 12', 'PESANAN TAMBAH KURANG', '<ol><li style="text-align: justify; ">PIHAK KESATU setiap saat dapat mengubah lingkup pelaksanaan Perjanjian seperti penambahan atau pengurangan pesanan Barang.</li><li style="text-align: justify; ">Jika perubahan dalam ayat (1) Pasal ini mengakibatkan penambahan atau pengurangan harga dan atau perubahan jadwal penyerahan barang pada SOP, maka akan dilakukan penyesuaian harga dan atau jadwal penyerahan Barang pada SOP, yang akan dituangkan dalam suatu surat perubahan SOP dan merupakan bagian yang tidak terpisahkan dari Perjanjian ini.</li><li style="text-align: justify; ">Harga satuan pesanan tambah kurang dalam\\ SOP tidak boleh melebihi dari harga satuan yang telah disepakati sebelumnya sebagaimana tercantum dalam dimaksud Pasal 7 Perjanjian ini.</li><li style="text-align: justify; ">Pesanan tambah kurang baru dapat dilaksanakan oleh PIHAK KEDUA setelah PIHAK KEDUA menerima Surat Pemberitahuan dari PIHAK KESATU mengenai perubahan pesanan tersebut.</li></ol>', 1, 1, 12, '2024-05-27 08:56:30', '2024-12-06 03:04:23'),
	(73, 'PASAL 13', 'JAMINAN MUTU BARANG', '<ol><li style="text-align: justify; ">PIHAK KEDUA memberikan Jaminan Mutu atas Barang dimana Barang yang dijual dan diserahkan kepada PIHAK KESATU adalah 100% (seratus persen) baru dan sesuai dengan ketentuan-ketentuan dan syarat-syarat yang ditetapkan dalam Perjanjian ini beserta Lampirannya, karena itu PIHAK KEDUA bertanggung jawab atas segala ketidaksesuaian mutu atas Barang termasuk tetapi tidak terbatas cacat tersembunyi ataupun kekurang sempurnaan dalam proses pembuatannya.</li><li style="text-align: justify; ">Masa Jaminan Mutu (garansi) atas barang menurut Perjanjian ini adalah selama 12 (dua belas) bulan setelah keluarnya Surat Penerimaan Barang (SPB) dari Gudang PIHAK KESATU.</li><li style="text-align: justify; ">Jaminan Mutu ini tidak berlaku bilamana dapat dibuktikan oleh PIHAK KEDUA bahwa ketidaksesuaian mutu atas Barang dimaksud Pasal ini disebabkan oleh karena kesalahan dalam pemakaian oleh PIHAK KESATU, namun yang terbukti bukan karena kesalahan dalam proses pembuatan ataupun juga karena kualitas bahan yang digunakan, hal mana harus dibuktikan oleh PIHAK KEDUA dan dapat meyakinkan PIHAK KESATU.</li><li style="text-align: justify; ">Dalam hal terjadi ketidaksesuaian mutu atas Barang dimaksud Pasal ini maka PIHAK KESATU akan memberitahukan secara tertulis dalam jangka waktu selambat-lambatnya 7 (tujuh) hari kalender setelah ketidaksesuaian mutu atas Barang tersebut ditemukan, PIHAK KEDUA berkewajiban untuk memperbaiki dan atau menggantikannya dengan Barang yang baru dalam waktu selambat-lambatnya 30 (tiga puluh) hari kalender terhitung sejak tanggal pemberitahuan dari PIHAK KESATU, kecuali apabila PIHAK KEDUA dapat membuktikan bahwa ketidaksesuaian mutu atas barang tersebut adalah terjadi karena sebab dimaksud ayat (3) Pasal ini.</li><li style="text-align: justify; ">Segala ongkos, biaya-biaya serta pengeluaran lain yang timbul karena penggantian dan atau perbaikan barang tersebut menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 1, 1, 13, '2024-05-27 08:58:36', '2024-12-06 03:37:26'),
	(74, 'PASAL 14', 'JAMINAN HUKUM ATAS BARANG', '<ol><li style="text-align: justify; ">PIHAK KEDUA menjamin bahwa Barang yang diserahkan kepada PIHAK KESATU tidak diperoleh dari hal-hal yang bertentangan dengan hukum.</li><li style="text-align: justify; ">PIHAK KEDUA menjamin bahwa Barang yang diserahkan berdasarkan Perjanjian ini tidak melanggar Hak Atas Kekayaan Intelektual (HAKI) atau hak lain yang dimiliki pihak ketiga.</li><li style="text-align: justify; ">Jika terjadi klaim atau tuntutan lainnya sehubungan dengan hal tersebut pada ayat (1) dan (2) Pasal ini, PIHAK KEDUA membebaskan PIHAK KESATU dari segala tuntutan apapun dan dimanapun yang mungkin timbul serta PIHAK KEDUA dengan ini menyatakan akan mengambil segala tindakan hukum yang diperlukan termasuk mewakili didepan Pengadilan.</li><li style="text-align: justify; ">Apabila klaim atau tuntutan pihak ketiga sebagaimana dimaksud ayat (1) dan (2) Pasal ini dikabulkan oleh Pengadilan atau oleh Badan apapun, maka PIHAK KEDUA menjamin bahwa Barang tersebut tetap dapat dipergunakan dan menjadi milik PIHAK KESATU.</li></ol>', 1, 1, 14, '2024-05-27 08:59:55', '2024-12-06 03:38:55'),
	(75, 'PASAL 15', 'SANKSI', '<ol><li style="text-align: justify; "><span style="font-size: 1rem;">Apabila jadwal penyerahan Barang sebagaimana dimaksud Pasal 5 Perjanjian ini terlampaui&nbsp;</span>maka PIHAK KEDUA akan dikenakan sanksi berupa denda keterlambatan sebesar 1<b style="color: rgb(31, 31, 31); font-family: " google="" sans",="" "helvetica="" neue",="" sans-serif;="" font-size:="" 14px;="" text-align:="" center;"="">‰</b>&nbsp;(satu permil) setiap hari kalender keterlambatan dari harga Barang seperti yang dimaksud Pasal 7 Perjanjian ini dengan batas maksimum denda keterlambatan sebesar 5% (lima persen) dari total harga Barang tersebut tidak termasuk Pajak Pertambahan Nilai (PPN), yang dapat dipotong secara sekaligus dari tagihan PIHAK KEDUA yang belum dibayar PIHAK KESATU.</li><li style="text-align: justify;">Apabila denda keterlambatan sudah mencapai batas maksimum sebagaimana dimaksud dalam ayat (1) Pasal ini atau waktu keterlambatan sudah mencapai 50 (lima puluh) hari kalender, maka PIHAK KEDUA dipandang tidak mampu untuk menyelesaikan Perjanjian ini, sehingga PIHAK KESATU berhak secara sepihak untuk memutuskan/membatalkan Perjanjian ini serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify;">Segala kerugian nyata yang disebabkan oleh keterlambatan seperti yang dimaksud Pasal ini akan dibebankan kepada PIHAK KEDUA, kerugian tersebut termasuk tetapi tidak terbatas denda pihak ketiga terhadap PIHAK KESATU dan biaya-biaya lain yang timbul.</li><li style="text-align: justify;">Segala kerugian nyata yang diderita PIHAK KESATU akibat ketidak sesuaian mutu atas barang seperti yang dimaksud Pasal 13 Perjanjian ini, dan/atau kesalahan PIHAK KEDUA, termasuk tetapi tidak terbatas pada denda pihak ketiga terhadap PIHAK KESATU akan dibebankan kepada PIHAK KEDUA.</li><li style="text-align: justify;">Apabila ternyata PIHAK KEDUA tidak dapat memenuhi ketentuan-ketentuan Perjanjian ini atau menurut pertimbangan PIHAK KESATU bahwa PIHAK KEDUA dipandang tidak mampu memenuhi ketentuan-ketentuan dalam Perjanjian ini, maka PIHAK KESATU secara sepihak berhak memutuskan/membatalkan Perjanjian ini. Hal yang sama dapat pula dilakukan apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang serta Jaminan Pelaksanaan (<i>Performance Bond</i>) menjadi milik PIHAK KESATU.</li><li style="text-align: justify;">Ketentuan sanksi seperti yang dimaksud Pasal ini tidak berlaku apabila :<ul><li style="text-align: justify;">Suatu keterlambatan seperti yang dimaksud Pasal ini disebabkan karena perintah secara tertulis\r\ndari PIHAK KESATU kepada PIHAK KEDUA untuk menunda atau menghentikan sementara waktu\r\npelaksanaan penyerahan barang seperti yang dimaksud Pasal 5 Perjanjian ini.</li><li style="text-align: justify;">PIHAK KEDUA dapat membuktikan dan dapat meyakinkan PIHAK KESATU bahwa segala ketidak sesuaian\r\nmutu atas Barang seperti yang dimaksud Pasal 13 Perjanjian ini adalah di luar kesalahan PIHAK KEDUA.&nbsp;<br></li></ul></li></ol>', 1, 1, 15, '2024-05-27 09:03:48', '2024-12-06 03:42:24'),
	(76, 'PASAL 16', 'KEADAAN MEMAKSA', '<ol><li>Yang dimaksud dengan Keadaan Memaksa adalah keadaan-keadaan yang disebabkan oleh kejadian-kejadian di luar kesalahan atau kekuasaan dari Para Pihak yang merintangi atau menghalangi pihak\r\ntersebut dalam menjalankan kewajibannya memenuhi Perjanjian ini, seperti :<ul><li>Gempa bumi besar, angin topan, banjir besar, kebakaran besar, tanah longsor dan wabah penyakit.</li><li>Pemogokan umum, huru-hara, sabotase, pemberontakan dan Kebijaksanaan Pemerintah di Bidang Moneter.</li><li>Kejadian-kejadian lain di luar kekuasaan atau kemampuan dari para pihak.<br></li></ul></li><li>Dalam hal Keadaan Memaksa yang dimaksud ayat (1) Pasal ini terjadi, maka pihak yang terkena Keadaan Memaksa\r\nwajib memberitahukan secara tertulis kepada pihak lainnya dalam jangka waktu 7 (tujuh) hari kalender dari sejak\r\nterjadinya Keadaan Memaksa dan diterangkan secara resmi oleh Pejabat yang berwenang mengeluarkannya.</li><li>Kelalaian atau keterlambatan pihak yang terkena Keadaan Memaksa dalam menyampaikan pemberitahuannya yang\r\ndimaksud ayat (2) Pasal ini, mengakibatkan tidak diakuinya peristiwa dimaksud ayat (1) Pasal ini sebagai peristiwa\r\nKeadaan Memaksa oleh pihak lainnya.</li><li>Kejadian-kejadian dimaksud dalam ayat (1) Pasal ini dapat diperhitungkan sebagai perpanjangan waktu kewajiban\r\nyang harus dilaksanakan oleh pihak yang terkena Keadaan Memaksa, apabila ketentuan dalam ayat (2) Pasal ini\r\ndipenuhi, dimana perpanjangan waktu tersebut akan dimusyawarahkan lebih lanjut oleh kedua belah pihak yang\r\nsyarat-syarat dan ketentuan-ketentuan disetujui bersama yang dituangkan dalam suatu Perjanjian baru.</li><li>Semua kerugian dan biaya-biaya yang diderita oleh salah satu pihak sebagai akibat Keadaan Memaksa bukan\r\nmerupakan tanggung jawab pihak lainnya.&nbsp;<br></li></ol>', 1, 1, 16, '2024-05-27 09:06:33', '2024-12-06 03:47:48'),
	(77, 'PASAL 17', 'PEMBATALAN PERJANJIAN', '<ol><li>PIHAK KESATU berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut\r\nPerjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi :<ul><li> Apabila PIHAK KEDUA terbukti tidak dapat menyelenggarakan Perjanjian yang dimaksud pada Pasal 4 dan 5 Perjanjian ini atau dipandang oleh PIHAK KESATU bahwa PIHAK KEDUA tidak mampu\r\nmelaksanakan Perjanjian dimaksud Pasal 3 Perjanjian ini.</li><li>Apabila PIHAK KEDUA telah memenuhi ketentuan Pasal 9 ayat (6) Perjanjian ini.</li><li>Apabila PIHAK KEDUA terbukti melanggar ketentuan Pasal 11 ayat (2) dan (3) Perjanjian ini.</li><li>Apabila PIHAK KEDUA gagal dalam memenuhi ketentuan Pasal 16 ayat (2) dan (4) Perjanjian ini.</li><li>Apabila PIHAK KEDUA dinyatakan jatuh pailit oleh yang berwenang.&nbsp;</li></ul></li><li>PIHAK KEDUA berhak secara sepihak untuk membatalkan sebagian atau seluruh Perjanjian menurut Perjanjian ini, apabila salah satu diantara sebab-sebab pembatalan di bawah ini terjadi :&nbsp;<ul><li>Apabila PIHAK KESATU dinyatakan jatuh pailit oleh yang berwenang.</li><li>Apabila PIHAK KESATU gagal dalam memenuhi ketentuan Pasal 16 ayat (2) dan (4) Perjanjian ini.</li></ul></li><li>Untuk hal ihwal pembatalan Perjanjian dimaksud ayat (1) Pasal ini, Para Pihak dengan ini menyatakan sepakat dan\r\nberjanji untuk mengesampingkan berlakunya ketentuan Pasal 1266 dan Pasal 1267 Undang-undang Hukum Perdata\r\nterhadap Perjanjian ini, sehingga pembatalan Perjanjian ini dapat dilakukan secara sah cukup dengan surat\r\npemberitahuan dari PIHAK KESATU kepada PIHAK KEDUA tanpa menunggu adanya keputusan dari Hakim serta\r\ndengan ini PIHAK KEDUA menyatakan melepaskan hak-hak yang timbul dari padanya apabila ada.</li><li>Dalam hal Perjanjian ini dibatalkan, maka Para Pihak secara bersama-sama mengadakan inventarisasi terhadap hak\r\ndan kewajiban yang ada dan apabila terdapat kekurangan atau kelebihan pembayaran oleh PIHAK KESATU, maka\r\nakan diadakan penambahan pembayaran oleh PIHAK KESATU atau pengembalian pembayaran oleh PIHAK\r\nKEDUA.</li><li>Dalam hal Perjanjian ini dibatalkan, maka PIHAK KEDUA dengan ini berjanji dan menyatakan membebaskan\r\nPIHAK KESATU dari segala tuntutan hukum, termasuk tuntutan dari pihak ketiga serta ganti rugi berupa apapun dan\r\ndari manapun karena batalnya Perjanjian ini, oleh karena itu sepenuhnya menjadi tanggung jawab PIHAK KEDUA.<br></li></ol>', 1, 1, 17, '2024-05-27 09:09:02', '2024-12-06 04:16:56'),
	(78, 'PASAL 18', 'PENYELESAIAN PERSELISIHAN', '<ol><li style="text-align: justify; ">Apabila dikemudian hari terjadi perselisihan dalam penafsiran dan atau pelaksanaan ketentuan-ketentuan dari Perjanjian ini dan atau hal-hal lainnya maka Para Pihak telah sepakat dan berjanji untuk terlebih dahulu menyelesaikan secara musyawarah untuk mencapai mufakat.</li><li style="text-align: justify; ">Bilamana cara musyawarah tersebut ayat (1) Pasal ini tidak dicapai kata sepakat dalam penyelesaian perselisihan, maka Para Pihak sepakat dan berjanji untuk menyelesaikan seluruh sengketa yang timbul dari Perjanjian ini kepada Badan Arbitrase Nasional Indonesia (BANI), untuk diselesaikan pada tingkat pertama dan terakhir menurut peraturan dan prosedur BANI.&nbsp; Arbitrase akan diselesaikan oleh 3 (tiga) orang Arbiter yang ditunjuk sebagai berikut :<ul><li style="text-align: justify; ">Masing-masing dari Para Pihak harus menunjuk 1 (satu) Arbiter dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal suatu permintaan untuk Arbitrase telah dikeluarkan oleh pihak yang meminta atau para pihak lain telah bersama-sama setuju membawa perselisihan kepada Arbitrase dan kedua Arbiter yang ditunjuk secara bersama-sama akan menunjuk Arbiter ketiga yang akan menjadi Ketua Arbitrase.</li><li style="text-align: justify; ">Apabila salah satu dari para pihak gagal menunjuk Arbiternya dalam jangka waktu sebagaimana dinyatakan di atas, Arbiter yang telah ditunjuk akan duduk sendiri sebagai Arbitrase dan memberikan Keputusan.</li><li style="text-align: justify; ">Namun apabila kedua Arbiter gagal menunjuk Arbiter ketiga dalam jangka waktu selambat-lambatnya 10 (sepuluh) hari kalender sejak tanggal penunjukan kedua Arbiter, maka Ketua BANI atau Pejabat BANI yang berwenang akan menunjuk Arbiter ketiga sebagai Ketua Arbiter atas permintaan salah satu pihak.</li></ul></li><li style="text-align: justify; ">Para pihak harus menanggung biaya Arbitrase secara sama rata dan proses Arbitrase harus dilangsungkan di Jakarta.</li><li style="text-align: justify; ">Kecuali dalam ayat (2) sub b. Pasal ini, Keputusan Badan Arbitrase diambil berdasarkan suara terbanyak dan bersifat mengikat kedua belah pihak terhadap para pihak.</li><li style="text-align: justify; ">Para pihak telah sepakat dan berjanji untuk secara tegas menentukan tidak ada banding atau penghentian pelaksanaan yang diajukan ke Pengadilan atas Keputusan Badan Arbitrase dan Para Pihak tidak akan menolak atau menentang pelaksanaan keputusan yang dilakukan oleh pihak untuk keuntungan siapa keputusan Badan Arbitrase telah diberikan.</li><li style="text-align: justify; ">Tiada satu pihak berhak untuk memulai atau melakukan tindakan di Pengadilan terhadap segala masalah dalam sengketa sampai dengan masalah tersebut telah diputuskan sebagaimana diatur di sini, kecuali untuk pelaksanaan keputusan Badan Arbitrase.</li><li style="text-align: justify; ">Selama proses Arbitrase dan sampai Arbitrase memberikan keputusannya, para pihak setuju untuk terus melaksanakan semua kewajibannya masing-masing berdasarkan Perjanjian ini tanpa berprasangka atau menduga atas putusan akhir yang diambil oleh para Arbiter tersebut.</li><li style="text-align: justify; ">Para pihak setuju memberlakukan penunjukan tidak akan berakhir pada tanggal setelah 6 (enam) bulan kalender sejak tanggal penunjukannya dan mandat kepada Arbitrase (wasit-wasit) sebagaimana yang ditetapkan sesuai dengan keputusan ini, akan tetap berlangsung sampai keputusan telah diambil oleh Badan Arbitrase.</li><li style="text-align: justify; ">Keputusan Badan Arbitrase dapat dilaksanakan di setiap Pengadilan dimanapun yang mempunyai yurisdiksi yang berwenang terhadap masing-masing para pihak atau harta kekayaannya.</li></ol>', 1, 1, 18, '2024-05-27 09:14:01', '2024-12-06 04:21:30'),
	(79, 'PASAL 19', 'KETENTUAN MENJAGA RAHASIA', '<ol><li style="text-align: justify; ">Para Pihak sepakat melakukan usaha-usaha mereka yang terbaik untuk menjaga kerahasiaan Informasi sehubungan dengan Perjanjian ini dan Para Pihak harus memastikan direktur-direktur, pegawai-pegawai, agen-agen atau pembantu-pembantu mereka tidak akan mengungkapkan informasi, data, dokumentasi dan pengetahuan kepada Pihak Ketiga tanpa persetujuan tertulis dari pihak yang lain, tidak juga akan menerbitkan informasi, data, dokumentasi dan pengetahuan dalam bentuk cetakan, kaset, disket, disk atau bentuk-bentuk lain, kecuali sepanjang tindakan dilakukan sebagai laporan kepada instansi pemerintah terkait sebagaimana diperlukan oleh undang-undang.</li><li style="text-align: justify; ">Kecuali informasi yang teridentifikasi dibuka oleh pihak pemberi informasi kepada pihak lain, bila dibuka secara tertulis berlabel "<i>proprietary</i>" atau "<i>confidential</i>" atau setiap label yang mempunyai arti yang semacam, atau bila dibuka secara lisan, yang harus dituangkan dalam tulisan dalam jangka waktu 30 (tiga puluh) hari dan berlabel "<i>proprietary</i>" atau "<i>confidential</i>" atau setiap label yang memiliki arti yang semacam (informasi rahasia) tetap menjadi milik pihak pemberi informasi.</li><li style="text-align: justify; ">Kecuali&nbsp; untuk hak-hak khusus yang diberikan oleh Perjanjian ini, pihak penerima informasi tidak boleh menggunakan setiap informasi rahasia untuk kepentingannya sendiri. Pihak penerima informasi harus menggunakan tingkatan pemeliharaan tertinggi yang wajar secara komersial untuk memproteksi informasi rahasia dari pihak pemberi informasi. Pihak penerima informasi tidak boleh membuka informasi rahasia kepada Pihak Ketiga manapun tanpa persetujuan tertulis yang tegas dari pihak pemberi informasi.</li><li style="text-align: justify; ">Informasi rahasia tidak mencakup informasi :&nbsp;<ul><li style="text-align: justify; ">Yang tersedia kepada pihak publik selain dari pada karena wanprestasi karena Perjanjian ini.</li><li style="text-align: justify; ">Yang secara sah diterima dari Pihak Ketiga yang tidak melanggar kewajiban kerahasiaan.</li><li style="text-align: justify; ">Yang secara independen dikebangkan oleh pihak penerima informasi tanpa akses pada informasi rahasia.</li><li style="text-align: justify; ">Yang diberitahukan kepada pihak penerima informasi pada waktu dilangsungkan keterbukaan; atau</li><li style="text-align: justify; ">Yang dibuat sesuai dengan ketentuan hukum atau perintah pengadilan, dengan ketentuan pihak pemberi informasi diberikan pengetahuan yang wajar mengenai ketentuan hukum atau perintah pengadilan tersebut dan kesempatan untuk mencabut untuk mengecualikan atau membatasi perbuatan tersebut.</li></ul></li><li style="text-align: justify; ">Pihak penerima informasi setuju untuk menghentikan penggunaan setiap dan semua bahan yang memuat informasi rahasia kepada pihak pemberi informasi ketika diminta.</li></ol>', 1, 1, 19, '2024-05-27 09:15:09', '2024-12-06 04:33:53'),
	(80, 'PASAL 20', 'HUKUM YANG BERLAKU', '<ol><li>Perjanjian ini tunduk dan berada dibawah ketentuan hukum Republik Indonesia.</li><li>PIHAK KEDUA harus mematuhi semua peraturan perundang-undangan dan kebijakan pemerintah&nbsp;<span style="font-size: 1rem;">yang berlaku di Indonesia.</span><br></li></ol>', 1, 1, 20, '2024-05-27 09:15:47', '2024-10-17 08:20:49'),
	(81, 'PASAL 21', 'PELINDUNGAN DATA PRIBADI', '<p style="text-align: justify; "><span style="font-family: Arial;">Para Pihak dengan ini mengakui dan memahami setiap kewajiban Para Pihak dalam upaya Pelindungan Data Pribadi sesuai dengan ketentuan yang berlaku, antara lain:</span></p><ol><li style="text-align: justify; "><span style="font-family: Arial;">Memproses Data Pribadi sesuai Undang-Undang Perlindungan Data Pribadi dan ketentuan dalam Peraturan Perundang-undangan lainnya.</span></li><li style="text-align: justify; "><span style="font-family: Arial;">Hanya memproses Data Pribadi apabila dan hanya sejauh diperlukan agar dapat melaksanakan kewajiban berdasarkan Perjanjian;</span></li><li style="text-align: justify; "><span style="font-family: Arial;">Tidak mengungkapkan Data Pribadi kepada pihak ketiga mana pun selain :</span><ul><li style="text-align: justify; "><span style="font-family: Arial;">Karyawan, direksi, afiliasi berdasarkan kebutuhan (</span><i style="font-size: 1rem;"><span style="font-family: Arial;">need-to know</span></i><span style="font-size: 1rem; font-family: Arial;">) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini;</span></li><li style="text-align: justify; "><span style="font-family: Arial;">Subkontraktor atau penasehat profesional yang diizinkan secara tertulis oleh Para Pihak untuk memproses Data Pribadi berdasarkan kebutuhan (</span><i style="font-size: 1rem;"><span style="font-family: Arial;">need-to know basis</span></i><span style="font-size: 1rem; font-family: Arial;">) sejauh diperlukan untuk melaksanakan kewajiban berdasarkan Perjanjian ini; atau</span></li><li style="text-align: justify; "><span style="font-family: Arial;">Sejauh diperlukan oleh peraturan perundang-undangan yang berlaku, namun tetap memperhatikan dan mematuhi Undang-Undang Perlindungan Data. Dalam hal tersebut, Pihak yang berkepentingan harus memberikan pemberitahuan tertulis kepada Pihak lainnya untuk mengungkapkan Data Pribadi (sejauh diizinkan oleh peraturan perundangan-undangan yang berlaku) segera mungkin setelah mengetahui persyaratan tersebut.</span></li></ul></li><li style="text-align: justify;"><span style="font-family: Arial;">Memastikan bahwa personilnya yang memproses Data Pribadi melaksanakan hal tersebut dan tetap patuh terhadap kewajiban kerahasiaan; dan</span></li><li style="text-align: justify;"><span style="font-family: Arial;">Melaksanakan dan mempertahankan tindakan atau langkah administratif, teknis dan organisasi yang cukup :</span><ul><li style="text-align: justify;"><span style="font-family: Arial;">Untuk menjaga keamanan Data Pribadi; dan</span></li><li style="text-align: justify;"><span style="font-family: Arial;">Untuk mencegah penghapusan tidak sah atau tidak disengaja, perubahan tidak sah, menyalin, mengakses atau menggunakan. pemalsuan. pencurian. kehilangan atau kesalahan teknis sehubungan dengan Data Pribadi.</span></li></ul></li><li style="text-align: justify;"><span style="font-family: Arial;">Para Pihak bertanggung jawab atas kerugian terhadap pelanggaran ketentuan terkait Data Pribadi yang diakibatkan oleh kelalaian personilnya serta akan bertanggung jawab penuh, termasuk namun tidak terbatas pada segala klaim, tuntutan, gugatan, sengketa, dan/atau kerugian yang mungkin timbul dari pelanggaran ketentuan terkait Data Pribadi.</span></li></ol>', 1, 1, 21, '2024-05-27 09:16:19', '2024-12-06 04:38:01'),
	(82, 'PASAL 22', 'LARANGAN PEMBERIAN HADIAH DAN KOMISI', '<ol><li style="text-align: justify; ">PIHAK KEDUA dilarang untuk menerima penawaran atau menyetujui pemberian hadiah, komisi, potongan atau bentuk-bentuk lain yang sejenis dari Direksi, staff/karyawan dari PIHAK KESATU untuk tujuan ditandatanganinya dan/atau pelaksanaan Perjanjian ini.</li><li style="text-align: justify; ">Pelanggaran terhadap ayat (1) Pasal ini oleh PIHAK KEDUA atau karyawannya atau pihak lain yang bekerja untuk PIHAK KEDUA dapat mengakibatkan pembatalan Perjanjian ini oleh PIHAK KESATU, dan biaya yang timbul dari pembatalan tersebut akan menjadi tanggung jawab PIHAK KEDUA, dan PIHAK KEDUA akan dieliminasi sebagai mitra bisnis PIHAK KESATU.</li><li style="text-align: justify; ">Pelanggaran dari setiap ketentuan dalam Pasal ini akan mengakibatkan gugatan pidana terhadap PIHAK KEDUA. Dalam hal terjadi penindaklanjutan atas adanya tindakan penerimaan komisi atau hadiah yang berpotensi merugikan PIHAK KESATU, semua biaya, ongkos dan kerugian yang timbul akan menjadi tanggung jawab PIHAK KEDUA.</li></ol>', 1, 1, 22, '2024-05-27 09:17:48', '2024-12-06 04:39:25'),
	(83, 'PASAL 23', 'TANGGAL BERLAKUNYA PERJANJIAN', '<p>Perjanjian ini berlaku efektif terhitung sejak ditandatanganinya Perjanjian ini oleh wakil Para Pihak yang berwenang.</p>', 1, 1, 23, '2024-05-27 09:18:38', '2024-05-27 09:18:38'),
	(84, 'PASAL 24', 'LAMPIRAN-LAMPIRAN', '<ol><li>Lampiran I&nbsp; &nbsp; &nbsp; :&nbsp; Dokumen-Dokumen Pengadaan</li><li>Lampiran II&nbsp; &nbsp; &nbsp;:&nbsp; Lingkup Perjanjian</li><li>Lampiran III&nbsp; &nbsp; :&nbsp; Spesifikasi Teknis</li><li>Lampiran IV&nbsp; &nbsp; :&nbsp; Jadwal Penyerahan Barang</li><li>Lampiran V&nbsp; &nbsp; &nbsp;:&nbsp; Harga Barang</li><li><span style="font-size: 1rem;">Lampiran VI&nbsp; &nbsp;&nbsp;</span>:&nbsp; Pembayaran</li><li><span style="font-size: 1rem;">Lampiran VII&nbsp; &nbsp;</span>:&nbsp; Alamat Surat Menyurat</li></ol>', 1, 1, 24, '2024-05-27 09:20:21', '2024-10-28 07:40:07'),
	(85, 'PASAL 25', 'LAIN-LAIN', '<ol><li style="text-align: justify; ">Hal-hal yang belum diatur dan perubahan-perubahan dari Perjanjian ini, akan diselesaikan melalui kesepakatan atau perundingan kedua belah pihak dan yang akan dituangkan dalam suatu Addendum Perjanjian yang ditandatangani oleh kedua belah pihak serta merupakan bagian yang tidak dapat dipisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li><li style="text-align: justify; ">Segala ketentuan-ketentuan dan syarat-syarat dalam Perjanjian ini berlaku serta mengikat bagi pihak-pihak yang menandatangani, pengganti-penggantinya dan mereka yang memperoleh keuntungan dari padanya.</li><li style="text-align: justify; ">Lampiran Perjanjian merupakan bagian yang tidak terpisahkan dari dan mempunyai kekuatan hukum yang sama dengan Perjanjian ini.</li></ol>', 1, 1, 25, '2024-05-27 09:21:22', '2024-05-27 09:21:22');
