INSERT INTO `vendor_texts` (`id`, `registration_no`, `akta`, `npwp`, `pihakname`, `created_at`, `updated_at`) VALUES
	(1, '00000120', '<p align="justify">yang dalam hal ini dalam jabatannya selaku Direktur dari dan oleh karena itu bertindak untuk dan atas nama PT. KERTAS PADALARANG, yang didirikan berdasarkan Akta Notaris Nomor : 04 tanggal 01 Juli 2020 yang dibuat oleh Notaris Aisyah Ratu Juliana Siregar, S.H., M.Kn. Notaris di Kota Sukabumi dan telah diubah untuk terakhir kalinya dengan Akta Notaris Nomor : 062 tanggal 04 Agustus 2023 yang dibuat oleh Notaris Dwi Suswanti, S.H., M.Kn. Notaris di Kota Cilegon yang dibuat berdasarkan Hukum Negara Republik Indonesia, yang berkedudukan hukum di Jalan Cihaliwung No.181 Padalarang, Padalarang, KAB. BANDUNG BARAT, JAWA BARAT, dengan Nomor Pokok Wajib Pajak (NPWP) Nomor: 01.000.015.6-051.000 yang untuk selanjutnya dalam perbuatan hukum ini disebut sebagai :</p>', '01.000.015.6-051.000', 'Yazi Deswan', '2024-12-09 06:40:20', '2024-12-09 06:40:20'),
	(2, '00000695', '<p align="justify">yang dalam hal ini dalam jabatannya selaku Direktur dari dan oleh karena itu bertindak untuk dan atas nama CV. MEGA ARTHA BARUNA, yang didirikan berdasarkan Akta Notaris Nomor : 04 tanggal 01 Juli 2020 yang dibuat oleh Notaris Aisyah Ratu Juliana Siregar, S.H., M.Kn. Notaris di Kota Sukabumi dan telah diubah untuk terakhir kalinya dengan Akta Notaris Nomor : 062 tanggal 04 Agustus 2023 yang dibuat oleh Notaris Dwi Suswanti, S.H., M.Kn. Notaris di Kota Cilegon yang dibuat berdasarkan Hukum Negara Republik Indonesia, yang berkedudukan hukum di&nbsp;<span style="text-align: left;">Taman Depok Permai Blok A11 No.5&nbsp;</span><span style="font-size: 1rem; text-align: left;">RT/RW:006/023, Cilodong, KOTA DEPOK, JAWA BARAT</span><span style="font-size: 1rem;">, dengan Nomor Pokok Wajib Pajak (NPWP) Nomor: </span>01.856.671.1-412.000<span style="font-size: 1rem;">&nbsp;yang untuk selanjutnya dalam perbuatan hukum ini disebut sebagai :</span></p>', '01.856.671.1-412.000', 'Susilo Unggul Rahardjo', '2024-12-09 07:17:25', '2024-12-09 07:17:25'),
	(3, '00000303', '<p align="justify">yang dalam hal ini dalam jabatannya selaku Direktur dari dan oleh karena itu bertindak untuk dan atas nama PT. Danisa Eka Abadi, yang didirikan berdasarkan Akta Notaris Nomor : 04 tanggal 01 Juli 2020 yang dibuat oleh Notaris Aisyah Ratu Juliana Siregar, S.H., M.Kn. Notaris di Kota Sukabumi dan telah diubah untuk terakhir kalinya dengan Akta Notaris Nomor : 062 tanggal 04 Agustus 2023 yang dibuat oleh Notaris Dwi Suswanti, S.H., M.Kn. Notaris di Kota Cilegon yang dibuat berdasarkan Hukum Negara Republik Indonesia, yang berkedudukan hukum di Jalan Sultan Iskandar Muda No. 181 Kota Administrasi Jakarta Selatan, dengan Nomor Pokok Wajib Pajak (NPWP) Nomor: 95.258.793.9-013.000 yang untuk selanjutnya dalam perbuatan hukum ini disebut sebagai :</p>', '03.007.507.1-056.000', 'Guntur Widjanarko', '2024-12-09 08:25:06', '2024-12-09 08:25:06');
